function load(){try{const x=JSON.parse(localStorage.getItem(KEY));return x||structuredClone(seed)}catch{return structuredClone(seed)}}
let state=load();
let cloudToken='';
let cloudSaveTimer=null;
function migrate(){const s=structuredClone(seed),old=state;for(const k of Object.keys(s)) if(old[k]!==undefined)s[k]=old[k];s.settings=Object.assign(structuredClone(seed.settings),old.settings||{});s.receipt=s.receipt||{};state=s;if(!state.levels)state.levels=structuredClone(seed.levels);if(!state.branches?.length)state.branches=structuredClone(seed.branches);if(!state.currentBranchId||!state.branches.some(b=>b.id===state.currentBranchId))state.currentBranchId=state.branches[0].id;if(!state.features.branches)state.features.branches=true;if(!state.stockVerifications)state.stockVerifications=[];
for(const k of ['customers','suppliers','stockConversions','stockVerifications','creditSales','creditRepayments','orders','stays','reservations','payments','stockMovements']){if(Array.isArray(state[k]))state[k].forEach(x=>{if(x&&x.branchId==null)x.branchId=state.currentBranchId||'b1'})}
if(Array.isArray(state.products))state.products.forEach(x=>{if(x&&x.branchId==null)x.branchId=state.currentBranchId||'b1'});if(!Array.isArray(state.categories)||!state.categories.length)state.categories=structuredClone(seed.categories);if(state.levels[2]&&!state.levels[2].features.includes('branches'))state.levels[2].features.push('branches');if(state.levels[3]&&!state.levels[3].features.includes('branches'))state.levels[3].features.push('branches');if(!state.users?.length)state.users=structuredClone(seed.users);const demoPasswords={ 'admin@harborpos.local':'HarborPOS123!','manager@harborpos.local':'HarborPOS123!','cashier@harborpos.local':'HarborPOS123!' };state.users=state.users.map(u=>({...u,password:(typeof u.password==='string'&&u.password)?u.password:(demoPasswords[String(u.email||'').toLowerCase()]||'HarborPOS123!'),active:u.active!==false}));if(!state.users.some(u=>String(u.email||'').toLowerCase()==='admin@harborpos.local'))state.users.unshift(structuredClone(seed.users[0]));if(!state.users[0]?.level)state.users[0].level=1;save()}migrate();
let tab='dashboard',cart=[],posq='',roomFilter='all',stayFilter='active',modalOpen=false,toaster=null;
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])), money=n=>new Intl.NumberFormat('en-KE',{style:'currency',currency:state.business.currency||'KES',maximumFractionDigits:0}).format(Number(n)||0);
function getSessionUserId(){try{return sessionStorage.getItem('harborpos_user_id')||localStorage.getItem('harborpos_user_id')||''}catch{return localStorage.getItem('harborpos_user_id')||''}} function setSessionUserId(id){try{sessionStorage.setItem('harborpos_user_id',id)}catch{} try{localStorage.setItem('harborpos_user_id',id)}catch{}} function clearSessionUserId(){try{sessionStorage.removeItem('harborpos_user_id')}catch{} try{localStorage.removeItem('harborpos_user_id')}catch{}} const sessionUserId=getSessionUserId; const currentUser=()=>state.users.find(u=>u.id===sessionUserId())||null; const branch=()=>{const u=currentUser();const b=state.branches.find(x=>x.id===state.currentBranchId)||state.branches[0]; if(u?.branchIds?.length && !u.branchIds.includes(b.id)) return state.branches.find(x=>x.id===u.branchIds[0])||b; return b};
function inBranch(record){return !record||record.branchId===state.currentBranchId}
function branchData(arr){return (arr||[]).filter(x=>inBranch(x))}
cloudToken=localStorage.getItem('harborpos_cloud_token')||'';
async function cloudApi(path,options={}){const opts={...options,headers:{'Content-Type':'application/json',...(options.headers||{})}};if(cloudToken)opts.headers.Authorization=`Bearer ${cloudToken}`;const r=await fetch(path,opts);let body={};try{body=await r.json()}catch{}if(!r.ok)throw new Error(body.error||`Request failed (${r.status})`);return body;}
function queueCloudSave(){if(!cloudToken)return;clearTimeout(cloudSaveTimer);cloudSaveTimer=setTimeout(async()=>{try{await cloudApi('/api/cloud/state',{method:'PUT',body:JSON.stringify(state)});localStorage.setItem('harborpos_last_cloud_sync',new Date().toISOString());}catch(e){console.warn('Cloud sync failed:',e.message)}},250)}
function save(){localStorage.setItem(KEY,JSON.stringify(state));queueCloudSave()}
function audit(action,entity,detail=''){state.audit.unshift({id:uid('AUD-'),at:new Date().toISOString(),user:currentUser()?.name||'System',action,entity,detail,branchId:state.currentBranchId});state.audit=state.audit.slice(0,500);save()}
function toast(t){const e=$('toast');if(!e)return;e.textContent=t;e.style.display='block';clearTimeout(toaster);toaster=setTimeout(()=>e.style.display='none',2500)}
function can(feature){const u=currentUser(),level=state.levels[u?.level||5];return level?.features.includes('*')||level?.features.includes(feature)}
function guard(feature,msg='Access restricted for your staff level'){if(!can(feature)){toast(msg);return false}return true}
function loginView(){return `<div class="login-screen"><div class="login-card"><div class="login-brand"><div class="brandmark">HP</div><div><div class="brandname">HarborPOS</div><div class="brandtag">Restaurants • Bars • Hotels</div></div></div><h1>Sign in</h1><p>Access your HarborPOS workspace.</p><div class="field"><label>Email<input id="loginEmail" type="email" autocomplete="username" placeholder="admin@harborpos.local"></label></div><div class="field"><label>Password<input id="loginPassword" type="password" autocomplete="current-password" placeholder="Enter password" onkeydown="if(event.key==='Enter')login()"></label></div><div id="loginError" class="login-error" style="display:none"></div><button class="btn primary full" onclick="login()">Sign in</button><div class="demo-credentials"><b>Demo accounts</b><span>Owner: admin@harborpos.local / HarborPOS123!</span><span>Manager: manager@harborpos.local / HarborPOS123!</span><span>Cashier: cashier@harborpos.local / HarborPOS123!</span></div></div></div>`}
async function login(){const email=($('loginEmail')?.value||'').trim().toLowerCase(),password=$('loginPassword')?.value||'';const e=$('loginError');if(e){e.style.display='none';e.textContent=''}if(!email||!password){if(e){e.textContent='Enter your email and password.';e.style.display='block'}return}try{const remote=await cloudApi('/api/auth/login',{method:'POST',body:JSON.stringify({email,password})});cloudToken=remote.token||'';if(cloudToken)localStorage.setItem('harborpos_cloud_token',cloudToken);const local=state; if(remote.state){state=remote.state; if(remote.user&&!state.users)state.users=[remote.user];} else {state=local; if(remote.user){const idx=state.users.findIndex(x=>x.id===remote.user.id||String(x.email||'').toLowerCase()===email);if(idx>=0)state.users[idx]={...state.users[idx],...remote.user};else state.users.push({...remote.user,password});} if(remote.branches?.length)state.branches=remote.branches.map(b=>({id:b.id,name:b.name,code:b.code,location:b.location,active:b.active})); if(!state.currentBranchId&&state.branches?.[0])state.currentBranchId=state.branches[0].id; await cloudApi('/api/cloud/state',{method:'PUT',body:JSON.stringify(state)});}migrate();setSessionUserId(remote.user.id);if(remote.user.branchIds?.length&&!remote.user.branchIds.includes(state.currentBranchId))state.currentBranchId=remote.user.branchIds[0];audit('User signed in','auth',remote.cloud?'Cloud database':'Server persistent data');save();render();return}catch(err){console.warn('Central login unavailable; using local demo login:',err.message)}const u=state.users.find(x=>String(x.email||'').toLowerCase()===email&&String(x.password||'')===password&&x.active!==false);if(!u){if(e){e.textContent='Invalid email or password.';e.style.display='block'}return}setSessionUserId(u.id);if(u.branchIds?.length)state.currentBranchId=u.branchIds[0];audit('User signed in','auth','Local fallback');save();render()}
function logout(){audit('User signed out','auth');clearSessionUserId();tab='dashboard';cart=[];render()}
function navItems(){const all=[['dashboard','Dashboard','⌂'],['branches','Branches','▦'],['pos','Point of Sale','▣'],['customers','Customers','♙'],['suppliers','Suppliers','◫'],['products','Stock & Products','□'],['conversions','Stock Conversions','⇄'],['credit','Credit Customers','◈'],['repayments','Credit Repayments','↻'],['rooms','Rooms','▰'],['reservations','Reservations','◷'],['stays','Front Desk','●'],['payments','Payments','◉'],['reports','Reports & PDFs','▥'],['users','Staff & Access','◆'],['settings','Settings','⚙']];return all.filter(x=>can(x[0]));}
function render(){if(!currentUser()){document.getElementById('app').innerHTML=loginView();return}const nav=navItems();if(!nav.some(n=>n[0]===tab))tab='dashboard';document.getElementById('app').innerHTML=`<div class="shell"><main class="main"><header class="topbar"><div class="top-left"><div class="brand-inline"><div class="brandmark">HP</div><div><div class="brandname">HarborPOS</div><div class="brandtag">Restaurants • Bars • Hotels</div></div></div><div><div class="crumb">${esc(branch()?.name||'Main Branch')} • OPERATIONS CENTER</div><div class="page-title">${nav.find(x=>x[0]===tab)?.[1]||'Dashboard'}</div></div></div><div class="top-right"><div class="online"><i></i>Operational</div><div class="branch-inline"><span>Branch</span><select onchange="switchBranch(this.value)">${state.branches.map(b=>`<option value="${b.id}" ${b.id===state.currentBranchId?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div><div class="mini-pill">Level ${currentUser().level}</div><div class="avatar">${(currentUser().name||'HP').split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase()}</div><button class="btn small" onclick="logout()">Logout</button></div></header><nav class="topnav" aria-label="HarborPOS features">${nav.map(n=>`<button class="navbtn ${tab===n[0]?'active':''}" onclick="go('${n[0]}')" title="${esc(n[1])}"><b>${n[2]}</b><span>${n[1]}</span></button>`).join('')}</nav><div class="content">${view()}</div></main><div id="toast" class="toast" style="display:none"></div></div>`}
function view(){return ({dashboard,branches,pos,customers,suppliers,products,conversions,credit,repayments,rooms,reservations,stays,payments,reports,users,settings}[tab]||dashboard)()}
function metric(ic,l,v,s){return `<div class="metric"><div class="metric-icon">${ic}</div><div><label>${l}</label><strong>${v}</strong><small>${s}</small></div></div>`}
function tag(s){return `<span class="tag ${s}"><i></i>${String(s).replace('-', ' ')}</span>`}
function empty(t,s){return `<div class="empty"><div class="empty-mark">□</div><b>${t}</b><span>${s}</span></div>`}
function dashboard(){const os=state.orders.filter(o=>o.branchId===state.currentBranchId),sales=os.reduce((a,o)=>a+o.total,0),occ=state.rooms.filter(r=>r.branchId===state.currentBranchId&&r.status==='occupied').length,avail=state.rooms.filter(r=>r.branchId===state.currentBranchId&&r.status==='available').length,debts=branchData(state.customers).reduce((a,c)=>a+(c.balance||0),0);return `<div class="page"><div class="hero"><div class="hero-copy"><span class="eyebrow">✦ OPERATIONS OVERVIEW</span><h1>Run your property with clarity.</h1><p>Sales, hotel stays, inventory, credit, staff access and downloadable reports.</p><div class="hero-actions">${can('pos')?'<button class="btn light" onclick="go(\'pos\')">+ New sale</button>':''}${can('reservations')?'<button class="btn light" onclick="reservationModal()">+ Reservation</button>':''}</div></div><div class="hero-visual"><img src="assets/harborpos-dashboard-mockup.png" alt="HarborPOS dashboard, POS and hotel management preview" loading="eager"></div></div><div class="grid4">${metric('◉','Sales today',money(sales),`${os.length} receipts`)}${metric('▰','Occupied rooms',occ,`${avail} available`)}${metric('♙','Customers',state.customers.length,'Customer accounts')}${metric('◈','Credit balance',money(debts),'Outstanding')}</div><div class="cols2"><section class="panel"><div class="panel-head"><div><h3>Recent sales</h3><p>Latest POS transactions</p></div><button class="btn" onclick="go('reports')">View reports →</button></div><div class="table-wrap"><table><thead><tr><th>Receipt</th><th>Customer</th><th>Payment</th><th>Total</th><th></th></tr></thead><tbody>${os.slice(0,7).map(o=>`<tr><td><b>${o.id}</b></td><td>${esc(state.customers.find(c=>c.id===o.customerId)?.name||'Walk-in')}</td><td>${esc(o.method)} ${o.reference?`<small>${esc(o.reference)}</small>`:''}</td><td><b>${money(o.total)}</b></td><td><button class="btn small danger" onclick="deleteEntity('order','${o.id}')">Delete</button></td></tr>`).join('')||`<tr><td colspan="4">${empty('No sales yet','Create a sale from the POS.')}</td></tr>`}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h3>Room status</h3><p>Live room inventory</p></div><button class="btn" onclick="go('rooms')">Manage rooms</button></div><div class="room-mini">${branchData(state.rooms).map(r=>`<div class="room-row"><div class="room-no">${r.no}</div><div><b>${esc(r.type)}</b><span>${money(r.price)} / night</span></div>${tag(r.status)}</div>`).join('')}</div></section></div><div class="cols3"><div class="action"><div class="card-icon">♙</div><h3>Customers & credit</h3><p>Customer balances, credit sales and repayments.</p><button onclick="go('customers')">Open customers →</button></div><div class="action"><div class="card-icon">⇄</div><h3>Inventory</h3><p>Stock, suppliers and unit conversions.</p><button onclick="go('products')">Open inventory →</button></div><div class="action"><div class="card-icon">⇩</div><h3>PDF center</h3><p>Reports for every operational feature.</p><button onclick="go('reports')">Open PDFs →</button></div></div></div>`}
function pos(){const ps=branchData(state.products).filter(p=>p.active&&p.canBeSold!==false&&(!posq||p.name.toLowerCase().includes(posq.toLowerCase())||p.category.toLowerCase().includes(posq.toLowerCase())));const subtotal=cart.reduce((a,x)=>a+x.price*x.qty,0),tax=Math.round(subtotal*(state.business.tax||0)),total=subtotal+tax;return `<div class="page"><div class="pos"><section class="panel menu-panel"><div class="menu-head"><div><h3>Menu</h3><p>Click an item to add it to the current sale.</p></div><input class="search" placeholder="Search menu..." value="${esc(posq)}" oninput="posq=this.value;render()"></div><div class="chips"><button class="chip ${!posq?'active':''}" onclick="posq='';render()">All</button><button class="chip" onclick="posq='Food';render()">Food</button><button class="chip" onclick="posq='Drinks';render()">Drinks</button></div><div class="product-grid">${ps.map(p=>`<button class="product" ${p.stock<1&&!state.settings.inventory.negativeStock?'disabled':''} onclick="addCart('${p.id}')"><div class="product-top">▣</div><b>${esc(p.name)}</b><small>${esc(p.category)} • ${p.stock} ${p.unit}</small><div class="price">${money(p.price)}</div></button>`).join('')}</div></section><section class="panel cart"><div class="panel-head"><div><h3>Current sale</h3><p>${cart.reduce((a,x)=>a+x.qty,0)} items</p></div><span class="mini-pill">${state.business.currency}</span></div><div class="cart-list">${cart.length?cart.map(x=>`<div class="cart-item"><div><b>${esc(x.name)}</b><span class="muted">${money(x.price)} each</span></div><div class="qty"><button onclick="qty('${x.id}',-1)">−</button><b>${x.qty}</b><button onclick="qty('${x.id}',1)">+</button></div><b>${money(x.qty*x.price)}</b></div>`).join(''):empty('Your cart is empty','Choose products from the menu.')}</div><div class="totals"><div><span>Subtotal</span><b>${money(subtotal)}</b></div><div><span>Tax</span><b>${money(tax)}</b></div><div class="grand"><span>Total</span><strong>${money(total)}</strong></div><button class="charge" ${!cart.length?'disabled':''} onclick="checkoutModal()">◉ Charge ${money(total)}</button></div></section></div></div>`}
function addCart(id){if(!guard('pos'))return;const p=state.products.find(x=>x.id===id);if(!p)return;if(!state.settings.inventory.negativeStock&&p.stock<1){toast('Out of stock');return}const f=cart.find(x=>x.id===id);if(f)f.qty++;else cart.push({...p,qty:1});render()}
function qty(id,d){const x=cart.find(i=>i.id===id);if(!x)return;x.qty+=d;if(x.qty<1)cart=cart.filter(i=>i.id!==id);render()}
function checkoutModal(){if(!cart.length)return;const subtotal=cart.reduce((a,x)=>a+x.price*x.qty,0),tax=Math.round(subtotal*(state.business.tax||0)),total=subtotal+tax;const custOptions=branchData(state.customers).map(c=>`<option value="${c.id}">${esc(c.name)} (${money(c.balance||0)})</option>`).join('');modal(`<div class="modal-icon">◉</div><h3>Complete sale</h3><p>Total due <b>${money(total)}</b></p><div class="form-grid"><div class="field"><label>Customer<select id="saleCustomer"><option value="">Walk-in customer</option>${custOptions}</select></label></div><div class="field"><label>Payment method<select id="saleMethod"><option>Cash</option><option>M-Pesa</option><option>Card</option><option>Bank</option><option>Credit</option></select></label></div><div class="field"><label>Customer / table note<input id="saleNote" placeholder="e.g. Table 12"></label></div><div class="field" id="cashTenderField"><label>Cash received<input id="saleCashTendered" type="number" min="0" step="1" placeholder="Enter amount received"></label><small class="small-note">Expected change: <b id="saleChange">${money(0)}</b></small></div></div><div id="mpesaVerifyBox" class="verify-box" style="display:none"><b>M-Pesa verification</b><p>The sale will remain pending until a matching M-Pesa SMS is received.</p><button class="btn" onclick="verifyPendingMpesa()">↻ Verify SMS now</button><span id="mpesaVerifyStatus"></span></div><div class="modal-row"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="startSale()">Complete payment</button></div>`);const sync=()=>{const method=$('saleMethod').value;const isCash=method==='Cash';$('cashTenderField').style.display=isCash?'block':'none';$('mpesaVerifyBox').style.display=method==='M-Pesa'?'block':'none';const received=Number($('saleCashTendered')?.value)||0;const change=Math.max(0,received-total);if($('saleChange')){$('saleChange').textContent=money(change);$('saleChange').className=received<total?'danger-text':'success-text'}};$('saleMethod').addEventListener('change',sync);$('saleCashTendered').addEventListener('input',sync);sync()}
function startSale(){const subtotal=cart.reduce((a,x)=>a+x.price*x.qty,0),tax=Math.round(subtotal*(state.business.tax||0)),total=subtotal+tax,method=$('saleMethod').value,customerId=$('saleCustomer').value||'',note=$('saleNote').value||'',cashTendered=Number($('saleCashTendered')?.value)||0;if(method==='Cash'&&cashTendered<total){toast(`Cash received must be at least ${money(total)}`);$('saleCashTendered')?.focus();return}if(method==='Credit'){if(!customerId){toast('Select a customer for credit');return}return createCreditSale(total,customerId,note)}const o={id:uid('ORD-'),date:today(),time:new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}),customerId,items:cart.map(x=>({...x})),subtotal,tax,total,method,note,branchId:state.currentBranchId,cashier:currentUser().name,paymentStatus:method==='M-Pesa'?'pending':'paid',cashTendered:method==='Cash'?cashTendered:0,change:method==='Cash'?Math.max(0,cashTendered-total):0};if(method==='M-Pesa'){state.orders.unshift(o);state.payments.unshift({id:uid('PAY-'),orderId:o.id,amount:total,method,status:'pending',reference:'',at:new Date().toISOString(),branchId:state.currentBranchId});save();audit(`M-Pesa sale ${o.id} pending verification`,'payment',money(total));cart=[];render();setTimeout(()=>openMpesaVerification(o.id),50);return}finalizeSale(o,'paid','')}
function finalizeSale(o,status,reference){o.paymentStatus=status;o.reference=reference||'';state.orders.unshift(o);state.payments.unshift({id:uid('PAY-'),orderId:o.id,amount:o.total,method:o.method,status,reference:reference||'',cashTendered:o.cashTendered||0,change:o.change||0,at:new Date().toISOString(),branchId:state.currentBranchId});state.products=state.products.map(p=>{const x=o.items.find(i=>i.id===p.id);return x?{...p,stock:p.stock-x.qty}:p});audit(`Sale ${o.id} completed`,'order',`${o.method} ${money(o.total)} ${reference||''}`);if(status==='paid'){closeModal();toast(`Payment recorded • ${o.id}`);setTimeout(()=>pdfReceipt(o),100)}else toast('Payment pending verification');cart=[];save();render()}
function createCreditSale(total,customerId,note){const c=state.customers.find(x=>x.id===customerId);if(!c)return;if((c.balance||0)+total>(c.creditLimit||0)){toast('Customer credit limit exceeded');return}const subtotal=cart.reduce((a,x)=>a+x.price*x.qty,0),tax=Math.round(subtotal*(state.business.tax||0)),o={id:uid('ORD-'),date:today(),time:new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}),customerId,items:cart.map(x=>({...x})),subtotal,tax,total,method:'Credit',note,branchId:state.currentBranchId,cashier:currentUser().name,paymentStatus:'credit'};state.orders.unshift(o);state.payments.unshift({id:uid('PAY-'),orderId:o.id,amount:0,method:'Credit',status:'credit',reference:'',at:new Date().toISOString(),branchId:state.currentBranchId});state.creditSales.unshift({id:uid('CR-'),orderId:o.id,customerId,amount:total,dueDate:new Date(Date.now()+(state.settings.credit.defaultDueDays||30)*86400000).toISOString().slice(0,10),status:'open',branchId:state.currentBranchId});c.balance=(c.balance||0)+total;state.products=state.products.map(p=>{const x=o.items.find(i=>i.id===p.id);return x?{...p,stock:p.stock-x.qty}:p});cart=[];audit(`Credit sale ${o.id}`,'credit',`${c.name} ${money(total)}`);save();closeModal();toast('Credit sale recorded');render();setTimeout(()=>pdfReceipt(o),100)}
function openMpesaVerification(orderId){const o=state.orders.find(x=>x.id===orderId);if(!o)return;modal(`<div class="modal-icon">◆</div><h3>Verify M-Pesa payment</h3><p>Order <b>${o.id}</b> • Amount <b>${money(o.total)}</b></p><div class="verify-box"><div><b>SMS Enabler</b><span id="mpesaStatus">Checking incoming SMS…</span></div><button class="btn primary" onclick="verifyPendingMpesa('${o.id}')">↻ Check again</button><button class="btn" onclick="simulateMpesaSms('${o.id}')">Simulate SMS</button></div><div class="small-note">Live mode reads SMS forwarded by SMS Enabler to the HarborPOS webhook. Demo mode can simulate a Safaricom-style confirmation.</div>`);verifyPendingMpesa(orderId)}
async function verifyPendingMpesa(orderId){const st=$('mpesaStatus')||$('mpesaVerifyStatus');if(st)st.textContent=' Checking…';try{const r=await fetch('/api/mpesa/messages?since='+encodeURIComponent(new Date(Date.now()-state.settings.mpesa.verificationWindow*60000).toISOString()));if(!r.ok)throw Error('server');const data=await r.json();state.smsInbox=data.messages||[];save();const o=state.orders.find(x=>x.id===orderId);const match=(data.messages||[]).map(m=>({m,mp:m.mpesa||parseLocalMpesa(m.message)})).find(x=>x.mp.isMpesa&&x.mp.amount!==null&&Math.abs(x.mp.amount-o.total)<=Number(state.settings.mpesa.tolerance||1));if(match){o.paymentStatus='paid';o.reference=match.mp.reference||match.m.messageId||'';const p=state.payments.find(x=>x.orderId===o.id);if(p){p.status='paid';p.reference=o.reference}state.products=state.products.map(p=>{const x=o.items.find(i=>i.id===p.id);return x?{...p,stock:p.stock-x.qty}:p});audit(`M-Pesa verified ${o.id}`,'payment',o.reference);save();toast('M-Pesa payment verified');closeModal();setTimeout(()=>pdfReceipt(o),100);render()}else if(st)st.textContent=' No matching SMS found yet.'}catch{if(st)st.textContent=' Live webhook server not reachable. Use Simulate SMS for local demo.'}}
function parseLocalMpesa(t){const x=String(t||'').replace(/\s+/g,' '),amount=(x.match(/K(?:ES)?\s*([0-9][0-9,]*(?:\.\d{1,2})?)/i)||[])[1];return{isMpesa:/m-?pesa|safaricom|mpesa/i.test(x),amount:amount?Number(amount.replace(/,/g,'')):null,reference:(x.match(/\b([A-Z]{2,6}\d{5,})\b/i)||[])[1]||''}}
async function simulateMpesaSms(orderId){const o=state.orders.find(x=>x.id===orderId);if(!o)return;const message=`Confirmed. KES ${o.total}.00 received from Jane Wanjiku. M-PESA reference QP${Math.floor(100000+Math.random()*900000)}.`;try{await fetch('/api/mpesa/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,sender:state.settings.mpesa.sender})});toast('Demo M-Pesa SMS sent to verifier');verifyPendingMpesa(orderId)}catch{state.smsInbox.unshift({id:uid('SMS-'),sender:'MPESA',message,receivedAt:new Date().toISOString(),mpesa:parseLocalMpesa(message)});save();verifyPendingMpesa(orderId)}}
function customers(){const list=branchData(state.customers);return `<div class="page"><div class="intro"><div><h2>Customers</h2><p>Customer profiles, balances, credit limits and account statements.</p></div><div class="actions"><button class="btn" onclick="pdfCustomers()">⇩ PDF</button><button class="btn primary" onclick="customerModal()">+ Add customer</button></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Phone</th><th>Credit limit</th><th>Balance</th><th>Status</th><th></th></tr></thead><tbody>${list.map(c=>`<tr><td><b>${esc(c.name)}</b><small>${esc(c.email||'')}</small></td><td>${esc(c.phone||'')}</td><td>${money(c.creditLimit||0)}</td><td><b class="${c.balance>0?'danger-text':''}">${money(c.balance||0)}</b></td><td>${tag(c.status)}</td><td><button class="btn small" onclick="customerModal('${c.id}')">Edit</button><button class="btn small" onclick="customerStatement('${c.id}')">Statement</button><button class="btn small danger" onclick="deleteEntity('customer','${c.id}')">Delete</button></td></tr>`).join('')}</tbody></table></div></section></div>`}
function customerModal(id){const c=state.customers.find(x=>x.id===id)||{name:'',phone:'',email:'',address:'',creditLimit:0,status:'active'};modal(`<div class="modal-icon">♙</div><h3>${id?'Edit':'Add'} customer</h3><div class="form-grid"><div class="field"><label>Name<input id="cn" value="${esc(c.name)}"></label></div><div class="field"><label>Phone<input id="cp" value="${esc(c.phone||'')}"></label></div><div class="field"><label>Email<input id="ce" value="${esc(c.email||'')}"></label></div><div class="field"><label>Address<input id="ca" value="${esc(c.address||'')}"></label></div><div class="field"><label>Credit limit<input id="cl" type="number" value="${c.creditLimit||0}"></label></div><div class="field"><label>Status<select id="cs"><option ${c.status==='active'?'selected':''}>active</option><option ${c.status==='inactive'?'selected':''}>inactive</option></select></label></div></div><button class="btn primary full" onclick="saveCustomer('${id||''}')">Save customer</button>`)}
function saveCustomer(id){const name=$('cn').value.trim();if(!name)return;const old=state.customers.find(x=>x.id===id);const c={id:id||uid('C-'),name,phone:$('cp').value.trim(),email:$('ce').value.trim(),address:$('ca').value.trim(),creditLimit:Number($('cl').value)||0,balance:id?(old?.balance||0):0,status:$('cs').value,branchId:old?.branchId||state.currentBranchId};if(id)state.customers=state.customers.map(x=>x.id===id?c:x);else state.customers.unshift(c);audit(`${id?'Customer updated':'Customer added'} ${name}`,'customer');save();closeModal();toast('Customer saved');render()}
function customerStatement(id){const c=state.customers.find(x=>x.id===id);if(c)pdfCustomerStatement(c)}
function suppliers(){const list=branchData(state.suppliers);return `<div class="page"><div class="intro"><div><h2>Suppliers</h2><p>Supplier contacts and outstanding supplier balances.</p></div><div class="actions"><button class="btn" onclick="pdfSuppliers()">⇩ PDF</button><button class="btn primary" onclick="supplierModal()">+ Add supplier</button></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Supplier</th><th>Phone</th><th>Tax PIN</th><th>Balance</th><th>Status</th><th></th></tr></thead><tbody>${list.map(s=>`<tr><td><b>${esc(s.name)}</b><small>${esc(s.email||'')}</small></td><td>${esc(s.phone||'')}</td><td>${esc(s.taxPin||'')}</td><td>${money(s.balance||0)}</td><td>${tag(s.status)}</td><td><button class="btn small" onclick="supplierModal('${s.id}')">Edit</button><button class="btn small danger" onclick="deleteEntity('supplier','${s.id}')">Delete</button></td></tr>`).join('')}</tbody></table></div></section></div>`}
function supplierModal(id){const s=state.suppliers.find(x=>x.id===id)||{name:'',phone:'',email:'',taxPin:'',address:'',balance:0,status:'active'};modal(`<div class="modal-icon">◫</div><h3>${id?'Edit':'Add'} supplier</h3><div class="form-grid"><div class="field"><label>Name<input id="sn" value="${esc(s.name)}"></label></div><div class="field"><label>Phone<input id="sp" value="${esc(s.phone||'')}"></label></div><div class="field"><label>Email<input id="se" value="${esc(s.email||'')}"></label></div><div class="field"><label>Tax PIN<input id="st" value="${esc(s.taxPin||'')}"></label></div><div class="field"><label>Address<input id="sa" value="${esc(s.address||'')}"></label></div><div class="field"><label>Status<select id="ss"><option>active</option><option>inactive</option></select></label></div></div><button class="btn primary full" onclick="saveSupplier('${id||''}')">Save supplier</button>`)}
function saveSupplier(id){const name=$('sn').value.trim();if(!name)return;const old=state.suppliers.find(x=>x.id===id);const s={id:id||uid('SUP-'),name,phone:$('sp').value,email:$('se').value,taxPin:$('st').value,address:$('sa').value,balance:old?.balance||0,status:$('ss').value,branchId:old?.branchId||state.currentBranchId};if(id)state.suppliers=state.suppliers.map(x=>x.id===id?s:x);else state.suppliers.unshift(s);audit(`${id?'Supplier updated':'Supplier added'} ${name}`,'supplier');save();closeModal();toast('Supplier saved');render()}
function products(){const list=branchData(state.products);return `<div class="page"><div class="intro"><div><h2>Stock & products</h2><p>Menu items, categories, costs, prices, units and stock levels.</p></div><div class="actions"><button class="btn" onclick="categoryModal()">▦ Categories</button><button class="btn" onclick="pdfProducts()">⇩ PDF</button><button class="btn" onclick="pdfStockVerification()">⇩ Verification PDF</button><button class="btn primary" onclick="stockVerificationModal()">✓ Verify stock</button><button class="btn primary" onclick="replenishStockModal()">＋ Replenish stock</button><button class="btn primary" onclick="productModal()">+ Add product</button></div></div><section class="panel"><div class="panel-head"><div><h3>Item categories</h3><p>${state.categories.length} categories available for products and POS reporting.</p></div><button class="btn small" onclick="categoryModal()">Manage categories</button></div><div class="chips">${state.categories.map(c=>`<button class="chip" onclick="filterProductsByCategory('${esc(c)}')">${esc(c)}</button>`).join('')}</div></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Selling</th><th>Cost</th><th>Stock</th><th>Unit</th><th>Sell</th><th>Convert</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${esc(p.category)}</td><td>${money(p.price)}</td><td>${money(p.cost||0)}</td><td class="${p.stock<state.settings.inventory.lowStock?'danger-text':''}">${p.stock}</td><td>${esc(p.unit)}</td><td>${p.canBeSold===false?'No':'Yes'}</td><td>${p.canBeConverted===false?'No':'Yes'}</td><td><button class="btn small" onclick="productModal('${p.id}')">Edit</button><button class="btn small" onclick="adjustStock('${p.id}')">Stock</button><button class="btn small danger" onclick="deleteEntity('product','${p.id}')">Delete</button></td></tr>`).join('')}</tbody></table></div></section></div>`}
function categoryModal(id){const current=id?state.categories.find(c=>c===id):'';modal(`<div class="modal-icon">▦</div><h3>Item categories</h3><p>Create and manage categories used across Stock & Products, POS and reports.</p><div class="form-grid"><div class="field full"><label>Category name<input id="catname" value="${esc(current)}" placeholder="e.g. Soft Drinks"></label></div></div><div class="category-list">${state.categories.map(c=>`<div class="category-row"><b>${esc(c)}</b><span><button class="btn small" onclick="categoryModal('${esc(c)}')">Edit</button><button class="btn small danger" onclick="deleteCategory('${esc(c)}')">Delete</button></span></div>`).join('')}</div><button class="btn primary full" onclick="saveCategory('${esc(current)}')">${current?'Save category':'Add category'}</button>`)}
function saveCategory(oldName=''){const name=$('catname').value.trim();if(!name){toast('Enter a category name');return}if(oldName){if(name!==oldName&&state.categories.includes(name)){toast('Category already exists');return}state.categories=state.categories.map(c=>c===oldName?name:c);state.products=state.products.map(p=>p.category===oldName?{...p,category:name}:p);audit(`Category renamed ${oldName} → ${name}`,'category')}else{if(state.categories.includes(name)){toast('Category already exists');return}state.categories.push(name);audit(`Category added ${name}`,'category')}save();closeModal();toast('Category saved');render()}
function deleteCategory(name){if(state.products.some(p=>p.category===name)){toast('Cannot delete: products use this category');return}state.categories=state.categories.filter(c=>c!==name);audit(`Category deleted ${name}`,'category');save();closeModal();toast('Category deleted');render()}
function filterProductsByCategory(category){go('products');setTimeout(()=>{document.querySelectorAll('.table-wrap table tbody tr').forEach(r=>{r.style.display=r.textContent.includes(category)?'':'none'})},0)}
function productModal(id){const p=state.products.find(x=>x.id===id)||{name:'',category:'Food',price:0,cost:0,stock:0,unit:'pcs',canBeSold:true,canBeConverted:true,active:true};modal(`<div class="modal-icon">□</div><h3>${id?'Edit':'Add'} product</h3><div class="form-grid"><div class="field"><label>Name<input id="pn" value="${esc(p.name)}"></label></div><div class="field"><label>Category<select id="pc">${state.categories.map(c=>`<option ${p.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label></div><div class="field"><label>Selling price<input id="pp" type="number" min="0" value="${p.price}"></label></div><div class="field"><label>Cost price<input id="pk" type="number" min="0" value="${p.cost||0}"></label></div><div class="field"><label>Current stock<input id="ps" type="number" min="0" value="${p.stock}"></label></div><div class="field"><label>Unit<input id="pu" value="${esc(p.unit||'pcs')}"></label></div><div class="field full"><label>Can be sold? <select id="pbs"><option value="1" ${p.canBeSold!==false?'selected':''}>Yes — available on POS</option><option value="0" ${p.canBeSold===false?'selected':''}>No — cannot be sold</option></select></label></div><div class="field full"><label>Can be converted? <select id="pbc"><option value="1" ${p.canBeConverted!==false?'selected':''}>Yes — allowed in stock conversions</option><option value="0" ${p.canBeConverted===false?'selected':''}>No — cannot be converted</option></select></label></div><div class="field full"><label>Active <select id="pact"><option value="1" ${p.active!==false?'selected':''}>Active</option><option value="0" ${p.active===false?'selected':''}>Inactive</option></select></label></div></div><button class="btn primary full" onclick="saveProduct('${id||''}')">Save product</button>`)}
function saveProduct(id){const name=$('pn').value.trim(),price=Number($('pp').value);if(!name||price<0)return;const p={id:id||uid('P-'),name,category:$('pc').value,price,cost:Number($('pk').value)||0,stock:Math.max(0,Number($('ps').value)||0),unit:$('pu').value.trim()||'pcs',canBeSold:$('pbs').value==='1',canBeConverted:$('pbc').value==='1',active:$('pact').value==='1',branchId:state.currentBranchId};if(id)state.products=state.products.map(x=>x.id===id?p:x);else state.products.unshift(p);audit(`${id?'Product updated':'Product added'} ${name}`,'product',`Sold=${p.canBeSold}; Converted=${p.canBeConverted}`);save();closeModal();toast('Product saved');render()}
function replenishStockModal(){const items=state.products.filter(p=>p.branchId===state.currentBranchId&&p.active);if(!items.length){toast('No active products');return}modal(`<div class="modal-icon">＋</div><h3>Replenish stock</h3><p>Add received stock to your current branch and keep a supplier/reference trail.</p><div class="form-grid"><div class="field"><label>Product<select id="rp">${items.map(p=>`<option value="${p.id}">${esc(p.name)} — ${p.stock} ${esc(p.unit)}</option>`).join('')}</select></label></div><div class="field"><label>Quantity received<input id="rq" type="number" min="0.01" step="0.01" value="1"></label></div><div class="field"><label>Unit cost<input id="rc" type="number" min="0" step="0.01" value="0"></label></div><div class="field"><label>Supplier<select id="rs"><option value="">— None —</option>${branchData(state.suppliers).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label></div><div class="field"><label>Reference / GRN / Invoice<input id="rr" placeholder="e.g. GRN-1042"></label></div><div class="field full"><label>Reason / note<input id="rn" placeholder="Stock received from supplier"></label></div></div><button class="btn primary full" onclick="saveReplenishment()">Save replenishment</button>`)}
function saveReplenishment(){const p=state.products.find(x=>x.id===$('rp').value),q=Number($('rq').value)||0,cost=Number($('rc').value)||0;if(!p||q<=0){toast('Enter a valid product and quantity');return}const old=p.stock;p.stock+=q;state.stockMovements=state.stockMovements||[];state.stockMovements.unshift({id:uid('SM-'),date:today(),at:new Date().toISOString(),branchId:state.currentBranchId,productId:p.id,type:'replenishment',quantity:q,unitCost:cost,supplierId:$('rs').value||'',reference:$('rr').value.trim(),reason:$('rn').value.trim(),user:currentUser().name});audit(`Stock replenished ${p.name}`,'stock_replenishment',`${old} → ${p.stock}; qty ${q}; ref ${$('rr').value||'—'}`);save();closeModal();toast(`Stock replenished • ${p.name}`);render()}
function adjustStock(id){const p=state.products.find(x=>x.id===id);if(!p)return;modal(`<div class="modal-icon">⇄</div><h3>Adjust stock — ${esc(p.name)}</h3><p>Current stock: <b>${p.stock} ${p.unit}</b></p><div class="form-grid"><div class="field"><label>Movement<select id="sm"><option value="add">Add stock</option><option value="remove">Remove stock</option><option value="set">Set stock</option></select></label></div><div class="field"><label>Quantity<input id="sq" type="number" value="0"></label></div><div class="field"><label>Reason<input id="sr" placeholder="Purchase, wastage, count correction"></label></div></div><button class="btn primary full" onclick="saveStock('${id}')">Save stock</button>`)}
function saveStock(id){const p=state.products.find(x=>x.id===id),q=Number($('sq').value)||0,m=$('sm').value;if(!p||q<0)return;const old=p.stock;p.stock=m==='add'?old+q:m==='remove'?old-q:q;audit(`Stock adjusted ${p.name}`,'stock',`${old} → ${p.stock}; ${$('sr').value||''}`);save();closeModal();toast('Stock updated');render()}
function stockVerificationModal(){const items=state.products.filter(p=>p.branchId===state.currentBranchId&&p.active);if(!items.length){toast('No products to verify');return}modal(`<div class="modal-icon">✓</div><h3>Stock verification</h3><p>Enter the physical count. HarborPOS will compare it with the system balance and record any variance.</p><div class="table-wrap"><table><thead><tr><th>Item</th><th>System</th><th>Physical count</th><th>Variance</th></tr></thead><tbody>${items.map(p=>`<tr><td><b>${esc(p.name)}</b><small>${esc(p.unit)}</small></td><td>${p.stock}</td><td><input class="verify-count" data-id="${p.id}" type="number" min="0" value="${p.stock}" oninput="updateVerificationVariance()"></td><td id="var_${p.id}">0</td></tr>`).join('')}</tbody></table></div><div class="form-grid"><div class="field"><label>Verification note<input id="vnote" placeholder="Physical count, end of shift, monthly check..." ></label></div><div class="field"><label>Verified by<input id="vby" value="${esc(currentUser().name)}"></label></div></div><button class="btn primary full" onclick="saveStockVerification()">Save verification</button>`)}
function updateVerificationVariance(){document.querySelectorAll('.verify-count').forEach(i=>{const p=state.products.find(x=>x.id===i.dataset.id);const el=document.getElementById('var_'+i.dataset.id);if(!p||!el)return;const v=(Number(i.value)||0)-Number(p.stock);el.textContent=v>0?`+${v}`:String(v);el.className=v===0?'':'danger-text'})}
function saveStockVerification(){const counts=[...document.querySelectorAll('.verify-count')];if(!counts.length)return;const verification={id:uid('SV-'),date:today(),at:new Date().toISOString(),branchId:state.currentBranchId,verifiedBy:$('vby').value.trim()||currentUser().name,note:$('vnote').value.trim(),items:[]};for(const input of counts){const p=state.products.find(x=>x.id===input.dataset.id);if(!p)continue;const system=Number(p.stock)||0,physical=Math.max(0,Number(input.value)||0),variance=physical-system;verification.items.push({productId:p.id,name:p.name,unit:p.unit,system,physical,variance});if(variance!==0)p.stock=physical}state.stockVerifications.unshift(verification);audit('Stock verification completed','stock_verification',`Items: ${verification.items.length}; Variances: ${verification.items.filter(x=>x.variance!==0).length}`);save();closeModal();toast('Stock verification saved');render()}
function pdfStockVerification(){const v=state.stockVerifications.filter(x=>x.branchId===state.currentBranchId);const rows=[];for(const rec of v){for(const i of rec.items)rows.push({date:rec.date,verifiedBy:rec.verifiedBy,item:i.name,system:i.system,physical:i.physical,variance:i.variance>0?`+${i.variance}`:String(i.variance),note:rec.note||''})}savePdf('stock-verification.pdf','STOCK VERIFICATION REPORT',[{key:'date',label:'DATE'},{key:'verifiedBy',label:'VERIFIED BY'},{key:'item',label:'ITEM'},{key:'system',label:'SYSTEM'},{key:'physical',label:'PHYSICAL'},{key:'variance',label:'VARIANCE'},{key:'note',label:'NOTE'}],rows,[`Verification sessions: ${v.length}`,`Items checked: ${rows.length}`,`Items with variance: ${rows.filter(r=>r.variance!=='0').length}`])}
function conversions(){const rows=branchData(state.stockConversions);return `<div class="page"><div class="intro"><div><h2>Stock conversions</h2><p>Convert bulk units into sellable units, or reverse a conversion with an auditable adjustment.</p></div><div class="actions"><button class="btn" onclick="pdfConversions()">⇩ PDF</button><button class="btn primary" onclick="conversionModal()">+ New conversion</button></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Date</th><th>From</th><th>To</th><th>Input</th><th>Output</th><th>Reason</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr><td>${c.date}</td><td>${esc(c.fromName)}</td><td>${esc(c.toName)}</td><td>${c.inputQty} ${c.fromUnit}</td><td>${c.outputQty} ${c.toUnit}</td><td>${esc(c.reason||'')}</td><td><button class="btn small" onclick="editConversion('${c.id}')">Edit</button><button class="btn small danger" onclick="deleteEntity('conversion','${c.id}')">Delete</button></td></tr>`).join('')||`<tr><td colspan="7">${empty('No conversions','Convert stock between units here.')}</td></tr>`}</tbody></table></div></section></div>`}
function conversionModal(id){const c=state.stockConversions.find(x=>x.id===id)||{fromId:state.products[0]?.id,toId:state.products[0]?.id,inputQty:1,outputQty:1,reason:''};modal(`<div class="modal-icon">⇄</div><h3>${id?'Edit':'New'} stock conversion</h3><p>Example: 1 carton → 24 bottles.</p><div class="form-grid"><div class="field"><label>Source item<select id="cf">${branchData(state.products).map(p=>`<option value="${p.id}" ${p.id===c.fromId?'selected':''}>${esc(p.name)} (${p.unit})</option>`).join('')}</select></label></div><div class="field"><label>Destination item<select id="ct">${branchData(state.products).map(p=>`<option value="${p.id}" ${p.id===c.toId?'selected':''}>${esc(p.name)} (${p.unit})</option>`).join('')}</select></label></div><div class="field"><label>Input quantity<input id="ci" type="number" value="${c.inputQty}"></label></div><div class="field"><label>Output quantity<input id="co" type="number" value="${c.outputQty}"></label></div><div class="field full"><label>Reason<input id="cr" value="${esc(c.reason||'')}"></label></div></div><button class="btn primary full" onclick="saveConversion('${id||''}')">Save conversion</button>`)}
function editConversion(id){conversionModal(id)}
function saveConversion(id){const from=state.products.find(p=>p.id===$('cf').value),to=state.products.find(p=>p.id===$('ct').value),iq=Number($('ci').value)||0,oq=Number($('co').value)||0;if(!from||!to||iq<=0||oq<=0)return;const old=state.stockConversions.find(x=>x.id===id);if(old){const oldFrom=state.products.find(p=>p.id===old.fromId),oldTo=state.products.find(p=>p.id===old.toId);oldFrom.stock+=old.inputQty;oldTo.stock-=old.outputQty}from.stock-=iq;to.stock+=oq;const c={id:id||uid('CONV-'),date:today(),fromId:from.id,toId:to.id,fromName:from.name,toName:to.name,fromUnit:from.unit,toUnit:to.unit,inputQty:iq,outputQty:oq,reason:$('cr').value,branchId:state.currentBranchId};if(id)state.stockConversions=state.stockConversions.map(x=>x.id===id?c:x);else state.stockConversions.unshift(c);audit(`${id?'Conversion edited':'Conversion created'}`,'stock_conversion',`${from.name} ${iq} → ${to.name} ${oq}`);save();closeModal();toast('Conversion saved');render()}
function credit(){const rows=branchData(state.creditSales);return `<div class="page"><div class="intro"><div><h2>Credit customers</h2><p>Track credit sales, due dates, limits and outstanding balances.</p></div><div class="actions"><button class="btn" onclick="pdfCredit()">⇩ PDF</button><button class="btn primary" onclick="go('pos')">+ New credit sale</button></div></div><div class="grid4">${metric('◈','Open accounts',rows.filter(r=>r.status==='open').length,'Credit sales')}${metric('◈','Outstanding',money(branchData(state.customers).reduce((a,c)=>a+(c.balance||0),0)),'Customer debt')}${metric('↻','Repayments',money(state.creditRepayments.reduce((a,r)=>a+r.amount,0)),'Total received')}${metric('◉','Due soon',rows.filter(r=>r.status==='open'&&r.dueDate<=new Date(Date.now()+7*86400000).toISOString().slice(0,10)).length,'Next 7 days')}</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Sale</th><th>Amount</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(r=>{const c=state.customers.find(x=>x.id===r.customerId);return `<tr><td><b>${esc(c?.name||'')}</b></td><td>${r.orderId}</td><td>${money(r.amount)}</td><td>${r.dueDate}</td><td>${tag(r.status)}</td><td><button class="btn small" onclick="creditDetail('${r.id}')">Details</button><button class="btn small danger" onclick="deleteEntity('credit','${r.id}')">Delete</button></td></tr>`}).join('')||`<tr><td colspan="6">${empty('No credit sales','Credit sales created from the POS appear here.')}</td></tr>`}</tbody></table></div></section></div>`}
function creditDetail(id){const r=state.creditSales.find(x=>x.id===id),c=state.customers.find(x=>x.id===r.customerId);modal(`<div class="modal-icon">◈</div><h3>Credit account</h3><p><b>${esc(c.name)}</b> • Sale ${r.orderId}</p><p>Original credit: <b>${money(r.amount)}</b><br>Customer balance: <b>${money(c.balance||0)}</b><br>Due: <b>${r.dueDate}</b></p><div class="modal-row"><button class="btn primary" onclick="closeModal();go('repayments')">Record repayment</button><button class="btn" onclick="pdfCreditSale('${r.id}')">Download PDF</button></div>`) }
function repayments(){const rows=branchData(state.creditRepayments);return `<div class="page"><div class="intro"><div><h2>Credit repayments</h2><p>Record customer repayments and automatically reduce outstanding balances.</p></div><div class="actions"><button class="btn" onclick="pdfRepayments()">⇩ PDF</button><button class="btn primary" onclick="repaymentModal()">+ Record repayment</button></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Date</th><th>Customer</th><th>Amount</th><th>Method</th><th>Reference</th><th></th></tr></thead><tbody>${rows.map(r=>{const c=state.customers.find(x=>x.id===r.customerId);return `<tr><td>${r.date}</td><td>${esc(c?.name||'')}</td><td><b>${money(r.amount)}</b></td><td>${esc(r.method)}</td><td>${esc(r.reference||'')}</td><td><button class="btn small" onclick="repaymentModal('${r.id}')">Edit</button><button class="btn small danger" onclick="deleteEntity('repayment','${r.id}')">Delete</button></td></tr>`}).join('')||`<tr><td colspan="6">${empty('No repayments','Record a repayment to reduce a credit balance.')}</td></tr>`}</tbody></table></div></section></div>`}
function repaymentModal(id){const r=state.creditRepayments.find(x=>x.id===id)||{customerId:state.customers[0]?.id,amount:0,method:'Cash',reference:'',date:today(),note:''};modal(`<div class="modal-icon">↻</div><h3>${id?'Edit':'Record'} repayment</h3><div class="form-grid"><div class="field"><label>Customer<select id="rcust">${branchData(state.customers).map(c=>`<option value="${c.id}" ${c.id===r.customerId?'selected':''}>${esc(c.name)} — ${money(c.balance||0)} due</option>`).join('')}</select></label></div><div class="field"><label>Amount<input id="ramt" type="number" value="${r.amount}"></label></div><div class="field"><label>Method<select id="rmethod"><option>Cash</option><option>M-Pesa</option><option>Card</option><option>Bank</option></select></label></div><div class="field"><label>Reference<input id="rref" value="${esc(r.reference||'')}"></label></div><div class="field"><label>Date<input id="rdate" type="date" value="${r.date}"></label></div></div><button class="btn primary full" onclick="saveRepayment('${id||''}')">Save repayment</button>`)}
function saveRepayment(id){const customer=state.customers.find(c=>c.id===$('rcust').value),amount=Number($('ramt').value)||0;if(!customer||amount<=0)return;if(!id&&amount>(customer.balance||0)){toast('Repayment exceeds customer balance');return}const old=state.creditRepayments.find(x=>x.id===id);if(old){const oldC=state.customers.find(c=>c.id===old.customerId);oldC.balance+=(old.amount||0);customer.balance-=(old.amount||0)}customer.balance=Math.max(0,(customer.balance||0)-amount);const r={id:id||uid('REP-'),customerId:customer.id,amount,method:$('rmethod').value,reference:$('rref').value,date:$('rdate').value,note:'',branchId:state.currentBranchId};if(id)state.creditRepayments=state.creditRepayments.map(x=>x.id===id?r:x);else state.creditRepayments.unshift(r);state.creditSales.filter(x=>x.customerId===customer.id&&x.status==='open').forEach(x=>{if(customer.balance===0)x.status='paid'});audit(`${id?'Repayment updated':'Repayment recorded'}`,'credit_repayment',`${customer.name} ${money(amount)}`);save();closeModal();toast('Repayment saved');render();setTimeout(()=>pdfRepayment(r),100)}
function rooms(){const rows=branchData(state.rooms);const list=state.rooms.filter(r=>r.branchId===state.currentBranchId&&(roomFilter==='all'||r.status===roomFilter));return `<div class="page"><div class="intro"><div><h2>Rooms</h2><p>Room number, 1/2/3-bedroom type, price, details and live status.</p></div><div class="actions"><select class="select" onchange="roomFilter=this.value;render()"><option value="all">All</option><option value="available">Available</option><option value="occupied">Occupied</option><option value="maintenance">Maintenance</option></select><button class="btn" onclick="pdfRooms()">⇩ PDF</button><button class="btn primary" onclick="roomModal()">+ Add room</button></div></div><div class="room-grid">${list.map(r=>`<div class="room-card"><div class="room-top"><div class="room-badge">▰ <b>${esc(r.no)}</b></div>${tag(r.status)}</div><h3>${esc(r.type)}</h3><p>${esc(r.detail)}</p><div class="room-rate"><b>${money(r.price)}</b><span>per night</span></div><div class="room-actions">${r.status==='available'?`<button class="btn primary" onclick="checkinModal('${r.id}')">Check in</button>`:r.status==='occupied'?`<button class="btn" onclick="go('stays')">View stay</button>`:''}<button class="btn" onclick="roomModal('${r.id}')">Edit</button><button class="btn" onclick="roomDetail('${r.id}')">PDF</button><button class="btn danger" onclick="deleteEntity('room','${r.id}')">Delete</button></div></div>`).join('')}</div></div>`}
function roomModal(id){const r=state.rooms.find(x=>x.id===id)||{no:'',type:'1 Bedroom',price:0,detail:'',status:'available'};modal(`<div class="modal-icon">▰</div><h3>${id?'Edit':'Add'} room</h3><div class="form-grid"><div class="field"><label>Room number<input id="rn" value="${esc(r.no)}"></label></div><div class="field"><label>Room type<select id="rt"><option ${r.type==='1 Bedroom'?'selected':''}>1 Bedroom</option><option ${r.type==='2 Bedroom'?'selected':''}>2 Bedroom</option><option ${r.type==='3 Bedroom'?'selected':''}>3 Bedroom</option></select></label></div><div class="field"><label>Nightly price<input id="rr" type="number" value="${r.price}"></label></div><div class="field"><label>Status<select id="rs"><option>available</option><option>occupied</option><option>maintenance</option></select></label></div><div class="field full"><label>Room detail<input id="rd" value="${esc(r.detail)}"></label></div></div><button class="btn primary full" onclick="saveRoom('${id||''}')">Save room</button>`);$('rs').value=r.status}
function saveRoom(id){const no=$('rn').value.trim(),price=Number($('rr').value)||0;if(!no||price<=0)return;const r={id:id||uid('R-'),no,type:$('rt').value,bedrooms:Number($('rt').value[0]),price,detail:$('rd').value,status:$('rs').value,branchId:state.currentBranchId};if(id)state.rooms=state.rooms.map(x=>x.id===id?r:x);else state.rooms.unshift(r);audit(`${id?'Room updated':'Room added'} ${no}`,'room');save();closeModal();toast('Room saved');render()}
function roomDetail(id){const r=state.rooms.find(x=>x.id===id);pdfRoom(r)}
function checkinModal(roomId){const avail=state.rooms.filter(r=>r.branchId===state.currentBranchId&&r.status==='available');if(!avail.length){toast('No rooms available');return}const selected=roomId||avail[0].id;modal(`<div class="modal-icon">●</div><h3>Guest check-in</h3><div class="form-grid"><div class="field"><label>Guest name<input id="gn"></label></div><div class="field"><label>Phone<input id="gp"></label></div><div class="field"><label>Customer<select id="gc"><option value="">Create/use guest only</option>${branchData(state.customers).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label></div><div class="field"><label>Room<select id="gr">${avail.map(r=>`<option value="${r.id}" ${r.id===selected?'selected':''}>Room ${r.no} — ${r.type} — ${money(r.price)}</option>`).join('')}</select></label></div><div class="field"><label>Check-in<input id="gi" type="date" value="${today()}"></label></div><div class="field"><label>Check-out<input id="gco" type="date" value="${new Date(Date.now()+86400000).toISOString().slice(0,10)}"></label></div><div class="field"><label>Deposit<input id="gd" type="number" value="0"></label></div></div><button class="btn primary full" onclick="doCheckin()">Check in guest</button>`)}
function doCheckin(){const guest=$('gn').value.trim(),phone=$('gp').value.trim(),room=state.rooms.find(r=>r.id===$('gr').value),ci=$('gi').value,co=$('gco').value,deposit=Number($('gd').value)||0;if(!guest||!room||co<=ci){toast('Complete guest and valid dates');return}const nights=Math.max(1,Math.ceil((new Date(co)-new Date(ci))/86400000));let customerId=$('gc').value;if(!customerId){const c={id:uid('C-'),name:guest,phone,email:'',address:'',creditLimit:0,balance:0,status:'active',branchId:state.currentBranchId};state.customers.unshift(c);customerId=c.id}const stay={id:uid('STY-'),guest,phone,customerId,roomId:room.id,roomNo:room.no,checkIn:ci,checkOut:co,nights,total:nights*room.price,deposit,balance:Math.max(0,nights*room.price-deposit),status:'checked-in',branchId:state.currentBranchId};state.stays.unshift(stay);room.status='occupied';audit(`Guest ${guest} checked in`,'stay',`Room ${room.no}`);save();closeModal();toast('Guest checked in');render()}
function stays(){const rows=branchData(state.stays);const list=state.stays.filter(s=>s.branchId===state.currentBranchId&&(stayFilter==='all'||(stayFilter==='active'?s.status==='checked-in':s.status!=='checked-in')));return `<div class="page"><div class="intro"><div><h2>Front desk</h2><p>Check guests in, collect balances and complete checkout.</p></div><div class="actions"><select class="select" onchange="stayFilter=this.value;render()"><option value="active">Active</option><option value="all">All</option><option value="closed">Completed</option></select><button class="btn" onclick="pdfStays()">⇩ PDF</button><button class="btn primary" onclick="checkinModal()">+ Walk-in check-in</button></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Guest</th><th>Room</th><th>Stay</th><th>Nights</th><th>Total</th><th>Balance</th><th>Status</th><th></th></tr></thead><tbody>${list.map(s=>`<tr><td><b>${esc(s.guest)}</b><small>${esc(s.phone||'')}</small></td><td>${s.roomNo}</td><td>${s.checkIn} → ${s.checkOut}</td><td>${s.nights}</td><td>${money(s.total)}</td><td>${money(s.balance||0)}</td><td>${tag(s.status)}</td><td>${s.status==='checked-in'?`<button class="btn small" onclick="checkoutStay('${s.id}')">Check out</button>`:''}<button class="btn small" onclick="editStay('${s.id}')">Edit</button><button class="btn small" onclick="pdfStay('${s.id}')">PDF</button><button class="btn small danger" onclick="deleteEntity('stay','${s.id}')">Delete</button></td></tr>`).join('')||`<tr><td colspan="8">${empty('No stays','No records match this filter.')}</td></tr>`}</tbody></table></div></section></div>`}
function editStay(id){const s=state.stays.find(x=>x.id===id);if(!s)return;modal(`<div class="modal-icon">●</div><h3>Edit stay</h3><div class="form-grid"><div class="field"><label>Guest<input id="en" value="${esc(s.guest)}"></label></div><div class="field"><label>Phone<input id="ep" value="${esc(s.phone||'')}"></label></div><div class="field"><label>Check-out<input id="eco" type="date" value="${s.checkOut}"></label></div><div class="field"><label>Deposit<input id="ed" type="number" value="${s.deposit||0}"></label></div></div><button class="btn primary full" onclick="saveStay('${id}')">Save stay</button>`)}
function saveStay(id){const s=state.stays.find(x=>x.id===id);s.guest=$('en').value.trim();s.phone=$('ep').value.trim();s.checkOut=$('eco').value;s.deposit=Number($('ed').value)||0;s.nights=Math.max(1,Math.ceil((new Date(s.checkOut)-new Date(s.checkIn))/86400000));const room=state.rooms.find(r=>r.id===s.roomId);s.total=s.nights*(room?.price||0);s.balance=Math.max(0,s.total-s.deposit);audit(`Stay ${id} updated`,'stay');save();closeModal();toast('Stay updated');render()}
function checkoutStay(id){const s=state.stays.find(x=>x.id===id);if(!s)return;const balance=Math.max(0,s.balance||0);modal(`<div class="modal-icon">✓</div><h3>Check out ${esc(s.guest)}</h3><p>Room ${s.roomNo} • Balance due <b>${money(balance)}</b></p><div class="form-grid"><div class="field"><label>Payment method<select id="coMethod"><option>Cash</option><option>M-Pesa</option><option>Card</option><option>Bank</option></select></label></div><div class="field"><label>Amount to collect<input id="coAmount" type="number" value="${balance}"></label></div><div class="field full"><label>Reference<input id="coRef" placeholder="M-Pesa transaction code / card reference"></label></div></div><div class="verify-box" id="checkoutMpesa" style="display:none"><b>M-Pesa SMS verification</b><span id="checkoutStatus">Pending</span><button class="btn" onclick="verifyCheckoutMpesa('${id}')">↻ Verify SMS</button><button class="btn" onclick="simulateCheckoutMpesa('${id}')">Simulate SMS</button></div><div class="modal-row"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="completeCheckout('${id}')">Complete checkout</button></div>`);$('coMethod').addEventListener('change',e=>{$('checkoutMpesa').style.display=e.target.value==='M-Pesa'?'grid':'none'})}
async function verifyCheckoutMpesa(id){const s=state.stays.find(x=>x.id===id),amount=Number($('coAmount').value)||0;if(!s)return;const st=$('checkoutStatus');st.textContent=' Checking…';try{const r=await fetch('/api/mpesa/messages?since='+encodeURIComponent(new Date(Date.now()-state.settings.mpesa.verificationWindow*60000).toISOString()));const data=await r.json();state.smsInbox=data.messages||[];const match=(data.messages||[]).map(m=>({m,mp:m.mpesa||parseLocalMpesa(m.message)})).find(x=>x.mp.isMpesa&&x.mp.amount!==null&&Math.abs(x.mp.amount-amount)<=Number(state.settings.mpesa.tolerance||1));if(match){$('coRef').value=match.mp.reference||match.m.messageId||'';st.textContent=' Verified';st.dataset.verified='1';toast('M-Pesa matched to checkout amount')}else st.textContent=' No matching SMS yet'}catch{st.textContent=' Server unavailable — use a reference manually in demo mode'}}
async function simulateCheckoutMpesa(id){const amount=Number($('coAmount').value)||0;const message=`Confirmed. KES ${amount}.00 received from Guest. M-PESA reference CP${Math.floor(100000+Math.random()*900000)}.`;try{await fetch('/api/mpesa/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,sender:state.settings.mpesa.sender})});toast('Demo checkout SMS sent');verifyCheckoutMpesa(id)}catch{state.smsInbox.unshift({id:uid('SMS-'),sender:'MPESA',message,receivedAt:new Date().toISOString(),mpesa:parseLocalMpesa(message)});save();$('coRef').value=parseLocalMpesa(message).reference;$('checkoutStatus').textContent=' Verified';$('checkoutStatus').dataset.verified='1'}}
function completeCheckout(id){const s=state.stays.find(x=>x.id===id),method=$('coMethod').value,amount=Number($('coAmount').value)||0,ref=$('coRef').value.trim();if(!s)return;if(method==='M-Pesa'&&$('checkoutStatus')?.dataset.verified!=='1'){toast('Verify the M-Pesa SMS before checkout');return}s.balance=Math.max(0,(s.balance||0)-amount);s.checkoutPayment={method,amount,reference:ref,at:new Date().toISOString()};if(s.balance>0){toast(`Partial payment recorded. ${money(s.balance)} remains.`);audit(`Partial checkout payment for ${s.guest}`,'stay',money(amount));save();closeModal();render();return}s.status='checked-out';s.checkedOutAt=new Date().toISOString();state.rooms=state.rooms.map(r=>r.id===s.roomId?{...r,status:'available'}:r);audit(`Guest ${s.guest} checked out`,'stay',`Room ${s.roomNo} • ${method} ${money(amount)} ${ref}`);save();closeModal();toast('Guest checked out');render();setTimeout(()=>pdfStay(id),100)}
function reservations(){const rows=branchData(state.reservations);const list=state.reservations.filter(r=>r.branchId===state.currentBranchId);return `<div class="page"><div class="intro"><div><h2>Reservations</h2><p>Upcoming bookings and room allocation.</p></div><div class="actions"><button class="btn" onclick="pdfReservations()">⇩ PDF</button><button class="btn primary" onclick="reservationModal()">+ New reservation</button></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Guest</th><th>Room</th><th>Stay</th><th>Guests</th><th>Status</th><th></th></tr></thead><tbody>${list.map(r=>`<tr><td><b>${esc(r.guest)}</b><small>${esc(r.phone||'')}</small></td><td>Room ${r.roomNo}</td><td>${r.checkIn} → ${r.checkOut}</td><td>${r.adults}/${r.children}</td><td>${tag(r.status)}</td><td>${r.status==='confirmed'?`<button class="btn small" onclick="convertReservation('${r.id}')">Check in</button>`:''}<button class="btn small" onclick="reservationModal('${r.id}')">Edit</button><button class="btn small danger" onclick="deleteEntity('reservation','${r.id}')">Delete</button></td></tr>`).join('')}</tbody></table></div></section></div>`}
function reservationModal(id){const r=state.reservations.find(x=>x.id===id),avail=state.rooms.filter(x=>x.branchId===state.currentBranchId&&(x.status==='available'||x.id===r?.roomId));const x=r||{guest:'',phone:'',roomId:avail[0]?.id||'',checkIn:today(),checkOut:new Date(Date.now()+86400000).toISOString().slice(0,10),adults:2,children:0,status:'confirmed'};modal(`<div class="modal-icon">◷</div><h3>${id?'Edit':'New'} reservation</h3><div class="form-grid"><div class="field"><label>Guest<input id="rg" value="${esc(x.guest)}"></label></div><div class="field"><label>Phone<input id="rp" value="${esc(x.phone||'')}"></label></div><div class="field"><label>Room<select id="rrm">${avail.map(a=>`<option value="${a.id}" ${a.id===x.roomId?'selected':''}>Room ${a.no} — ${a.type} — ${money(a.price)}</option>`).join('')}</select></label></div><div class="field"><label>Check-in<input id="rci" type="date" value="${x.checkIn}"></label></div><div class="field"><label>Check-out<input id="rco" type="date" value="${x.checkOut}"></label></div><div class="field"><label>Adults<input id="ra" type="number" value="${x.adults}"></label></div><div class="field"><label>Children<input id="rch" type="number" value="${x.children}"></label></div></div><button class="btn primary full" onclick="saveReservation('${id||''}')">Save reservation</button>`)}
function saveReservation(id){const room=state.rooms.find(x=>x.id===$('rrm').value),guest=$('rg').value.trim(),ci=$('rci').value,co=$('rco').value;if(!room||!guest||co<=ci)return;const r={id:id||uid('RES-'),guest,phone:$('rp').value,roomId:room.id,roomNo:room.no,checkIn:ci,checkOut:co,adults:Number($('ra').value)||1,children:Number($('rch').value)||0,status:id?(state.reservations.find(x=>x.id===id)?.status||'confirmed'):'confirmed',branchId:state.currentBranchId};if(id)state.reservations=state.reservations.map(x=>x.id===id?r:x);else state.reservations.unshift(r);audit(`${id?'Reservation updated':'Reservation created'}`,'reservation',guest);save();closeModal();toast('Reservation saved');render()}
function convertReservation(id){const r=state.reservations.find(x=>x.id===id),room=state.rooms.find(x=>x.id===r.roomId);if(!r||!room)return;const nights=Math.max(1,Math.ceil((new Date(r.checkOut)-new Date(r.checkIn))/86400000));state.stays.unshift({id:uid('STY-'),guest:r.guest,phone:r.phone,customerId:'',roomId:r.roomId,roomNo:r.roomNo,checkIn:r.checkIn,checkOut:r.checkOut,nights,total:nights*room.price,deposit:0,balance:nights*room.price,status:'checked-in',branchId:r.branchId});room.status='occupied';r.status='checked-in';audit(`Reservation ${r.id} checked in`,'reservation',r.guest);save();go('stays')}
function payments(){const rows=branchPayments();const list=rows;return `<div class="page"><div class="intro"><div><h2>Payments</h2><p>Payment ledger with M-Pesa references and pending verification.</p></div><button class="btn" onclick="pdfPayments()">⇩ PDF</button></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Payment</th><th>Order</th><th>Method</th><th>Amount</th><th>Status</th><th>Reference</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td>${p.id}</td><td>${p.orderId||'—'}</td><td>${p.method}</td><td><b>${money(p.amount)}</b></td><td>${tag(p.status)}</td><td>${esc(p.reference||'')}</td><td><button class="btn small danger" onclick="deleteEntity('payment','${p.id}')">Delete</button></td></tr>`).join('')}</tbody></table></div></section></div>`}
function branches(){const total=state.branches.length;return `<div class="page"><div class="intro"><div><h2>Branches</h2><p>Manage every HarborPOS outlet, switch active branches, and keep operations separated by location.</p></div><div class="actions"><button class="btn" onclick="pdfBranches()">⇩ PDF</button><button class="btn primary" onclick="branchModal()">+ Add branch</button></div></div><div class="grid4">${metric('▦','Total branches',total,`${state.users.filter(u=>u.active).length} active staff`)}${metric('◉','Active branch',esc(branch()?.name||'—'),esc(branch()?.location||''))}${metric('◆','Staff assigned',state.users.filter(u=>u.branchIds?.includes(state.currentBranchId)).length,'Current branch')}${metric('▥','Reports scope','Branch','All operational PDFs use active branch')}</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Branch</th><th>Code</th><th>Location</th><th>Staff</th><th>Status</th><th></th></tr></thead><tbody>${state.branches.map(b=>`<tr><td><b>${esc(b.name)}</b>${b.id===state.currentBranchId?`<small class="branch-current">● Active branch</small>`:''}</td><td><span class="mini-pill">${esc(b.code)}</span></td><td>${esc(b.location||'')}</td><td>${state.users.filter(u=>u.branchIds?.includes(b.id)).length}</td><td>${tag(b.active===false?'inactive':'active')}</td><td class="actions">${b.id!==state.currentBranchId?`<button class="btn small primary" onclick="switchBranch('${b.id}')">Use branch</button>`:''}<button class="btn small" onclick="branchModal('${b.id}')">Edit</button><button class="btn small danger" onclick="deleteEntity('branch','${b.id}')">Delete</button></td></tr>`).join('')}</tbody></table></div></section></div>`}
function branchModal(id){const b=state.branches.find(x=>x.id===id)||{name:'',code:'',location:'',active:true};modal(`<div class="modal-icon">▦</div><h3>${id?'Edit':'Add'} branch</h3><p>Branches separate sales, stock, hotel rooms, payments and reports.</p><div class="form-grid"><div class="field"><label>Branch name<input id="brn" value="${esc(b.name)}"></label></div><div class="field"><label>Branch code<input id="brc" value="${esc(b.code)}"></label></div><div class="field full"><label>Location / address<input id="brl" value="${esc(b.location||'')}"></label></div><div class="field"><label>Status<select id="bra"><option value="1" ${b.active!==false?'selected':''}>Active</option><option value="0" ${b.active===false?'selected':''}>Inactive</option></select></label></div></div><button class="btn primary full" onclick="saveBranch('${id||''}')">Save branch</button>`)}
function saveBranch(id){const name=$('brn').value.trim(),code=$('brc').value.trim().toUpperCase(),location=$('brl').value.trim();if(!name||!code){toast('Branch name and code are required');return}if(state.branches.some(b=>b.code===code&&b.id!==id)){toast('Branch code already exists');return}const b={id:id||uid('BR-'),name,code,location,active:$('bra').value==='1'};if(id)state.branches=state.branches.map(x=>x.id===id?{...x, ...b}:x);else state.branches.push(b); if(!state.currentBranchId)state.currentBranchId=b.id;audit(`${id?'Branch updated':'Branch added'} ${name}`,'branch',`${code} • ${location}`);save();closeModal();toast('Branch saved');render()}
function pdfBranches(){savePdf('branches.pdf','BRANCH DIRECTORY REPORT',[{key:'name',label:'BRANCH'},{key:'code',label:'CODE'},{key:'location',label:'LOCATION'},{key:'staff',label:'STAFF'},{key:'status',label:'STATUS'}],state.branches.map(b=>({name:b.name,code:b.code,location:b.location||'',staff:state.users.filter(u=>u.branchIds?.includes(b.id)).length,status:b.active===false?'Inactive':'Active'})),[`Total branches: ${state.branches.length}`,`Active branch: ${branch()?.name||''}`])}

function users(){return `<div class="page"><div class="intro"><div><h2>Staff & access levels</h2><p>Every staff member inherits access from the assigned level. Owners can customize each level below.</p></div><button class="btn primary" onclick="userModal()">+ Add staff</button></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Staff</th><th>Role</th><th>Level</th><th>Branches</th><th>Status</th><th></th></tr></thead><tbody>${state.users.map(u=>`<tr><td><b>${esc(u.name)}</b><small>${esc(u.email)}</small></td><td>${esc(u.role)}</td><td><span class="mini-pill">${u.level}</span> ${esc(state.levels[u.level]?.name||'')}</td><td>${u.branchIds.map(id=>esc(state.branches.find(b=>b.id===id)?.name||id)).join(', ')}</td><td>${u.active?tag('active'):tag('inactive')}</td><td><button class="btn small" onclick="userModal('${u.id}')">Edit</button><button class="btn small danger" onclick="deleteEntity('user','${u.id}')">Delete</button></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h3>Level permissions</h3><p>Feature-by-feature access matrix.</p></div><button class="btn" onclick="pdfAccessMatrix()">⇩ PDF</button></div><div class="permissions">${[1,2,3,4,5].map(l=>`<div class="perm-row"><b>${esc(state.levels[l].name)}</b><span>${navItemsAll().map(f=>state.levels[l].features.includes('*')||state.levels[l].features.includes(f[0])?`<span class="mini-pill">${esc(f[1])}</span>`:'').join(' ')}</span><button class="btn small" onclick="levelModal(${l})">Edit access</button></div>`).join('')}</div></section></div>`}
function navItemsAll(){return [['dashboard','Dashboard'],['branches','Branches'],['pos','POS'],['customers','Customers'],['suppliers','Suppliers'],['products','Stock'],['conversions','Conversions'],['credit','Credit'],['repayments','Repayments'],['rooms','Rooms'],['reservations','Reservations'],['stays','Front Desk'],['payments','Payments'],['reports','Reports'],['users','Users'],['settings','Settings']]}
function userModal(id){const u=state.users.find(x=>x.id===id)||{name:'',email:'',password:'',role:'Cashier',level:4,branchIds:[state.currentBranchId],active:true};modal(`<div class="modal-icon">◆</div><h3>${id?'Edit':'Add'} staff</h3><p>${id?'Update the staff profile, access level, branches, or set a new website password.':'Create a staff login and assign the access level and branch permissions.'}</p><div class="form-grid"><div class="field"><label>Name<input id="un" value="${esc(u.name)}" autocomplete="name"></label></div><div class="field"><label>Email / Login<input id="ue" type="email" value="${esc(u.email)}" autocomplete="username"></label></div><div class="field"><label>Website password<input id="up" type="password" value="" placeholder="${id?'Leave blank to keep current password':'Create password'}" autocomplete="new-password"></label></div><div class="field"><label>Confirm password<input id="up2" type="password" value="" placeholder="Re-enter password" autocomplete="new-password"></label></div><div class="field"><label>Role<input id="ur" value="${esc(u.role)}"></label></div><div class="field"><label>Access level<select id="ul">${[1,2,3,4,5].map(l=>`<option value="${l}" ${u.level===l?'selected':''}>${esc(state.levels[l].name)}</option>`).join('')}</select></label></div><div class="field"><label>Status<select id="us"><option value="1" ${u.active?'selected':''}>Active</option><option value="0" ${!u.active?'selected':''}>Inactive</option></select></label></div><div class="field full"><label>Assigned branches</label><div class="check-grid">${state.branches.map(b=>`<label><input type="checkbox" class="userbranch" value="${b.id}" ${(u.branchIds||[]).includes(b.id)?'checked':''}> ${esc(b.name)} (${esc(b.code)})</label>`).join('')}</div></div></div><div class="muted" style="margin:8px 0 14px">Passwords are used only for the current demo login store. In production, store password hashes server-side.</div><button class="btn primary full" onclick="saveUser('${id||''}')">Save staff</button>`)}
function saveUser(id){const name=$('un').value.trim(),email=$('ue').value.trim().toLowerCase(),pw=$('up').value,pw2=$('up2').value;if(!name||!email){toast('Name and email are required');return}const old=state.users.find(x=>x.id===id);if(!id&&!pw){toast('Create a password for the new staff login');return}if(pw&&pw!==pw2){toast('Passwords do not match');return}if(pw&&pw.length<8){toast('Password must be at least 8 characters');return}if(state.users.some(x=>x.id!==id&&String(x.email||'').toLowerCase()===email)){toast('That email is already in use');return}const branchIds=[...document.querySelectorAll('.userbranch:checked')].map(x=>x.value);if(!branchIds.length){toast('Assign at least one branch');return}const u={id:id||uid('U-'),name,email,password:pw||(old?.password||'HarborPOS123!'),role:$('ur').value.trim()||'Staff',level:Number($('ul').value),branchIds,active:$('us').value==='1'};if(id)state.users=state.users.map(x=>x.id===id?{...x,...u}:x);else state.users.push(u);audit(`${id?'Staff updated':'Staff added'} ${name}`,'user',`Level ${u.level}; Branches ${branchIds.length}; Password ${pw?'changed/set':'unchanged'}`);save();closeModal();toast(id?'Staff updated successfully':'Staff login created successfully');render()}
function levelModal(level){const f=navItemsAll(),set=state.levels[level].features;modal(`<div class="modal-icon">◆</div><h3>Edit ${esc(state.levels[level].name)}</h3><p>Select the features this level can access.</p><div class="check-grid">${f.map(([id,n])=>`<label><input type="checkbox" class="lvlcb" value="${id}" ${set.includes('*')||set.includes(id)?'checked':''}> ${esc(n)}</label>`).join('')}</div><button class="btn primary full" onclick="saveLevel(${level})">Save level access</button>`)}
function saveLevel(level){const features=[...document.querySelectorAll('.lvlcb:checked')].map(x=>x.value);state.levels[level].features=features;state.users.forEach(u=>{if(u.level===level&&u.id==='u1'&&level!==1)u.level=level});audit(`Access level ${level} updated`,'access',features.join(', '));save();closeModal();toast('Level access saved');render()}
function settings(){return `<div class="page"><div class="intro"><div><h2>Settings</h2><p>Feature-by-feature configuration, M-Pesa/SMS Enabler setup, receipts and property options.</p></div><button class="btn primary" onclick="saveSettings()">Save settings</button></div><section class="settings-grid"><section class="panel form-panel"><h3>Business</h3><div class="form-grid"><div class="field"><label>Business name<input id="bn" value="${esc(state.business.name)}"></label></div><div class="field"><label>Location<input id="bl" value="${esc(state.business.location)}"></label></div><div class="field"><label>Phone<input id="bp" value="${esc(state.business.phone)}"></label></div><div class="field"><label>Tax %<input id="bt" type="number" value="${state.business.tax*100}"></label></div></div></section><section class="panel form-panel"><h3>M-Pesa + SMS Enabler</h3><p class="muted">SMS Enabler forwards incoming SMS to a web script; HarborPOS checks the amount/reference server-side before marking payments paid.</p><div class="form-grid"><div class="field"><label>Webhook URL<input id="mw" value="${esc(state.settings.mpesa.webhookUrl)}"></label></div><div class="field"><label>Webhook token<input id="mt" type="password" value="${esc(state.settings.mpesa.token)}"></label></div><div class="field"><label>M-Pesa sender name<input id="msender" value="${esc(state.settings.mpesa.sender)}"></label></div><div class="field"><label>Amount tolerance<input id="mtol" type="number" value="${state.settings.mpesa.tolerance}"></label></div><div class="field"><label>Verification window (minutes)<input id="mwin" type="number" value="${state.settings.mpesa.verificationWindow}"></label></div><div class="field"><label>Auto-verify checkout<select id="mauto"><option value="1" ${state.settings.mpesa.autoVerify?'selected':''}>Yes</option><option value="0" ${!state.settings.mpesa.autoVerify?'selected':''}>No</option></select></label></div><div class="field full"><label>Test mode<select id="mtest"><option value="1" ${state.settings.mpesa.testMode?'selected':''}>Enabled</option><option value="0" ${!state.settings.mpesa.testMode?'selected':''}>Disabled</option></select></label></div></div><div class="info">SMS Enabler should POST incoming SMS to your HTTPS webhook. Keep the token secret and server-side. The project includes <code>/api/smsenabler/incoming</code>.</div></section><section class="panel form-panel"><h3>Inventory settings</h3><div class="form-grid"><div class="field"><label>Allow negative stock<select id="neg"><option value="1" ${state.settings.inventory.negativeStock?'selected':''}>Yes</option><option value="0" ${!state.settings.inventory.negativeStock?'selected':''}>No</option></select></label></div><div class="field"><label>Low-stock alert level<input id="low" type="number" value="${state.settings.inventory.lowStock}"></label></div><div class="field"><label>Track cost<select id="cost"><option value="1" ${state.settings.inventory.trackCost?'selected':''}>Yes</option><option value="0" ${!state.settings.inventory.trackCost?'selected':''}>No</option></select></label></div></div></section><section class="panel form-panel"><h3>Credit settings</h3><div class="form-grid"><div class="field"><label>Credit enabled<select id="cren"><option value="1" ${state.settings.credit.enabled?'selected':''}>Yes</option><option value="0" ${!state.settings.credit.enabled?'selected':''}>No</option></select></label></div><div class="field"><label>Default due days<input id="days" type="number" value="${state.settings.credit.defaultDueDays}"></label></div><div class="field"><label>Default credit limit<input id="clim" type="number" value="${state.settings.credit.creditLimit}"></label></div></div></section><section class="panel form-panel"><h3>Receipt designer</h3><div class="form-grid"><div class="field"><label>Logo text<input id="rlogo" value="${esc(state.business.logoText)}"></label></div><div class="field"><label>Paper size<select id="rpaper"><option ${state.settings.receipt.paper==='80mm'?'selected':''}>80mm</option><option ${state.settings.receipt.paper==='58mm'?'selected':''}>58mm</option><option ${state.settings.receipt.paper==='A4'?'selected':''}>A4</option></select></label></div><div class="field full"><label>Footer<input id="rfoot" value="${esc(state.settings.receipt.footer)}"></label></div></div><div class="check-grid"><label><input id="r1" type="checkbox" ${state.settings.receipt.showLogo?'checked':''}> Logo</label><label><input id="r2" type="checkbox" ${state.settings.receipt.showAddress?'checked':''}> Address</label><label><input id="r3" type="checkbox" ${state.settings.receipt.showCashier?'checked':''}> Cashier</label><label><input id="r4" type="checkbox" ${state.settings.receipt.showCustomer?'checked':''}> Customer</label><label><input id="r5" type="checkbox" ${state.settings.receipt.showPayment?'checked':''}> Payment method</label><label><input id="r6" type="checkbox" ${state.settings.receipt.showReference?'checked':''}> Reference</label><label><input id="r7" type="checkbox" ${state.settings.receipt.showTax?'checked':''}> Tax</label></div><button class="btn" onclick="receiptPreview()">Preview receipt</button></section><section class="panel form-panel"><h3>Feature controls</h3><div class="check-grid">${['branches','pos','customers','suppliers','products','conversions','credit','repayments','rooms','reservations','stays','payments','reports','users'].map(k=>`<label><input type="checkbox" id="f_${k}" ${state.features[k]?'checked':''}> ${esc(k)}</label>`).join('')}</div></section><section class="panel form-panel"><h3>Data & security</h3><div class="modal-row"><button class="btn" onclick="exportData()">Export backup</button><label class="btn">Import backup<input hidden type="file" accept="application/json" onchange="importData(event)"></label><button class="btn danger" onclick="resetDemo()">Reset demo</button></div><p class="small-note">For production, use server-side authentication, HTTPS, a managed database, encrypted secrets and scheduled backups.</p></section></section></div>`}
function saveSettings(){state.business.name=$('bn').value.trim();state.business.location=$('bl').value.trim();state.business.phone=$('bp').value.trim();state.business.tax=(Number($('bt').value)||0)/100;state.business.logoText=$('rlogo').value.trim()||'HARBORPOS';state.settings.mpesa.webhookUrl=$('mw').value.trim();state.settings.mpesa.token=$('mt').value;state.settings.mpesa.sender=$('msender').value.trim()||'MPESA';state.settings.mpesa.tolerance=Number($('mtol').value)||0;state.settings.mpesa.verificationWindow=Number($('mwin').value)||30;state.settings.mpesa.autoVerify=$('mauto').value==='1';state.settings.mpesa.testMode=$('mtest').value==='1';state.settings.inventory.negativeStock=$('neg').value==='1';state.settings.inventory.lowStock=Number($('low').value)||10;state.settings.inventory.trackCost=$('cost').value==='1';state.settings.credit.enabled=$('cren').value==='1';state.settings.credit.defaultDueDays=Number($('days').value)||30;state.settings.credit.creditLimit=Number($('clim').value)||50000;state.settings.receipt.paper=$('rpaper').value;state.settings.receipt.footer=$('rfoot').value;['Logo','Address','Cashier','Customer','Payment','Reference','Tax'].forEach((x,i)=>state.settings.receipt[['showLogo','showAddress','showCashier','showCustomer','showPayment','showReference','showTax'][i]]=$('r'+(i+1)).checked);['branches','pos','customers','suppliers','products','conversions','credit','repayments','rooms','reservations','stays','payments','reports','users'].forEach(k=>state.features[k]=$('f_'+k).checked);audit('Settings updated','settings');save();toast('Settings saved');render()}
function receiptPreview(){const o=state.orders[0];modal(`<div class="modal-icon">▣</div><h3>Receipt designer preview</h3><div id="receiptPreview">${receiptHtml(o)}</div><button class="btn" onclick="closeModal();pdfReceipt(o)">Download this receipt</button>`)}
function receiptHtml(o){const c=state.customers.find(x=>x.id===o.customerId);return `<div class="receipt-preview"><div class="receipt-center">${state.settings.receipt.showLogo?`<b>${esc(state.business.logoText)}</b>`:''}${state.settings.receipt.showAddress?`<span>${esc(state.business.location)}</span><span>${esc(state.business.phone)}</span>`:''}<hr><span>${o.id} • ${o.date} ${o.time||''}</span>${state.settings.receipt.showCustomer&&c?`<span>Customer: ${esc(c.name)}</span>`:''}${state.settings.receipt.showCashier?`<span>Cashier: ${esc(o.cashier||'')}</span>`:''}<hr>${o.items.map(i=>`<div class="receipt-line"><span>${i.qty} × ${esc(i.name)}</span><b>${money(i.qty*i.price)}</b></div>`).join('')}<hr><div class="receipt-line"><span>Subtotal</span><b>${money(o.subtotal)}</b></div>${state.settings.receipt.showTax?`<div class="receipt-line"><span>Tax</span><b>${money(o.tax)}</b></div>`:''}<div class="receipt-line"><strong>TOTAL</strong><strong>${money(o.total)}</strong></div>${state.settings.receipt.showPayment?`<span>Payment: ${esc(o.method)}</span>`:''}${o.method==='Cash'&&o.cashTendered?`<span>Cash received: ${money(o.cashTendered)}</span><span>Change: ${money(o.change||0)}</span>`:''}${state.settings.receipt.showReference&&o.reference?`<span>Ref: ${esc(o.reference)}</span>`:''}<hr><span>${esc(state.settings.receipt.footer)}</span></div></div>`}
function branchPayments(){return state.payments.filter(p=>p.branchId===state.currentBranchId)}
function paymentTotal(method){return branchPayments().filter(p=>p.method===method&&p.status==='paid').reduce((a,p)=>a+(Number(p.amount)||0),0)}
function collectionTotal(){return branchData(state.creditRepayments).reduce((a,r)=>a+(Number(r.amount)||0),0)}
function reportRegistry(){return [
['Detailed Sales Report','Sales by receipt, customer, payment and amount','pdfDetailedSales'],
['Sales Report by Paymode','Sales grouped by Cash, M-Pesa, Bank and Credit','pdfSalesByPaymode'],
['Credit Customer Statement','Customer-level credit activity and balances','pdfCreditCustomerStatement'],
['Credit Customer Payments Report','Customer credit repayments collected','pdfCreditCustomerPayments'],
['Captured Orders Report','All captured POS orders, payment status and values','pdfCapturedOrders'],
['Orders Summary Report','Order count and value summary by status','pdfOrdersSummary'],
['Suppliers Report','Supplier master list and balances','pdfSuppliersReport'],
['Suppliers Statement Report','Supplier statement ledger','pdfSuppliersStatement'],
['Price List Report','Current selling price list by category','pdfPriceList'],
['Stock Balance Report','Current stock balance by item','pdfStockBalance'],
['Stock Balance by Store Report','Current stock grouped by branch/store','pdfStockBalanceByStore'],
['Stock Card Report','Item stock movement history','pdfStockCard'],
['Stock Replenishment Report','All stock replenishments and suppliers','pdfStockReplenishment'],
['Raw Material Requisition Report','Raw-material requisition activity','pdfRawMaterialRequisition'],
['Sales Report by Salesperson','Sales grouped by cashier/salesperson','pdfSalesBySalesperson'],
['Sales Report by Stores','Sales grouped by branch/store','pdfSalesByStores'],
['Collection by Store Report','Collections grouped by branch/store','pdfCollectionByStore'],
['Collection by Salesperson Report','Collections grouped by cashier/salesperson','pdfCollectionBySalesperson'],
['Stock Profit Analysis','Estimated sales margin by item','pdfStockProfitAnalysis'],
['Stock Sold Quantity Analysis','Quantities sold by item','pdfStockSoldQuantityAnalysis'],
['Stock Verification Report','Physical stock vs system balance','pdfStockVerification'],
['Stock Verification Lost Items Report','Verified negative variances','pdfStockVerificationLost'],
['Stock Verification Excess Items Report','Verified positive variances','pdfStockVerificationExcess'],
['Stock Conversion Report','Stock conversions between items/units','pdfConversions'],
['Supplier Statement Report','Supplier balance statement','pdfSupplierStatement'],
['Supplier Credit Payments Report','Supplier credit/payment records','pdfSupplierCreditPayments'],
['Credit Customer Sales & Payments Report','Credit sales matched with repayments','pdfCreditCustomerSalesPayments'],
['M-Pesa Received Payments Report','Verified M-Pesa receipts and references','pdfMpesa'],
['Credit Note Items Report','Credit note item register','pdfCreditNoteItems'],
['Credit Note by Order No Report','Credit notes by order number','pdfCreditNoteByOrder'],
['Detailed Sales Report by Customer','Sales detail grouped by customer','pdfDetailedSalesByCustomer'],
['Detailed Sales Report by Store','Sales detail grouped by store','pdfDetailedSalesByStore'],
['Detailed Sales Report by Item & Store','Sales detail grouped by item and store','pdfDetailedSalesByItemStore'],
['Sales Report by Item Category','Sales grouped by item category','pdfSalesByCategory'],
['Rooms Report','Room inventory, room type, rate and occupancy status','pdfRooms'],
['Reservations Report','Hotel reservations by guest, room, stay dates and status','pdfReservations'],
['Front Office Report','Guest stays, check-in/out status and outstanding balances','pdfStays'],
['Staff Report','Staff accounts, roles, levels and branch assignments','pdfStaff'],
['Access Levels Report','Access levels and feature permissions','pdfAccessLevels']
]}
function reports(){const cards=reportRegistry();return `<div class="page"><div class="intro"><div><h2>Reports & PDFs</h2><p>Professional operational reports for sales, collections, credit, suppliers, inventory and verification.</p></div><span class="mini-pill">${esc(branch()?.name||'Main Branch')}</span></div><section class="report-summary">${[['Cash',paymentTotal('Cash')],['M-Pesa',paymentTotal('M-Pesa')],['Bank',paymentTotal('Bank')],['Credit collections',collectionTotal()]].map(x=>`<div><span>${x[0]}</span><b>${money(x[1])}</b></div>`).join('')}</section><div class="report-toolbar"><input class="search" id="reportSearch" placeholder="Search reports..." oninput="filterReports(this.value)"><select id="reportGroupFilter" onchange="filterReportGroup(this.value)"><option value="all">All report groups</option><option value="sales">Sales & Orders</option><option value="credit">Credit</option><option value="suppliers">Suppliers</option><option value="stock">Stock & Inventory</option><option value="collections">Collections & Payments</option><option value="hotel">Hotel & Front Office</option><option value="security">Staff & Audit</option></select></div><div class="report-list" id="reportGrid">${cards.map((x,i)=>`<div class="report-row" data-report="${esc(x[0].toLowerCase())}" data-group="${reportGroup(x[0])}"><div class="report-number">${String(i+1).padStart(2,'0')}</div><div class="report-name"><b>${x[0]}</b><span>${x[1]}</span></div><button class="btn small" onclick="${x[2]}()">⇩ Download PDF</button></div>`).join('')}</div></div>`}
function reportGroup(name){const n=name.toLowerCase();if(/sales|orders|price/.test(n))return 'sales';if(/credit/.test(n))return 'credit';if(/supplier/.test(n))return 'suppliers';if(/stock|raw material/.test(n))return 'stock';if(/collection|mpesa|payments/.test(n))return 'collections';if(/room|reservation|stay|front office/.test(n))return 'hotel';if(/access|audit/.test(n))return 'security';return 'sales'}
function applyReportFilters(){const q=String(document.getElementById('reportSearch')?.value||'').toLowerCase().trim();const g=document.getElementById('reportGroupFilter')?.value||'all';document.querySelectorAll('#reportGrid .report-row').forEach(el=>{const text=el.dataset.report||'';const okText=!q||text.includes(q);const okGroup=g==='all'||el.dataset.group===g;el.style.display=(okText&&okGroup)?'':'none'})}
function filterReports(){applyReportFilters()}
function filterReportGroup(){applyReportFilters()}



function branchOrders(){return state.orders.filter(o=>o.branchId===state.currentBranchId)}
function branchOrdersAll(){return state.orders}
function productSales(){const map={};for(const o of branchOrders()){for(const i of o.items||[]){if(!map[i.id])map[i.id]={id:i.id,name:i.name,qty:0,sales:0,cost:0};map[i.id].qty+=i.qty;map[i.id].sales+=i.qty*i.price;const p=state.products.find(x=>x.id===i.id);map[i.id].cost+=i.qty*(p?.cost||0)}}return Object.values(map)}
function saveOpsReport(file,title,columns,rows,summary=[]){savePdf(file,title,columns,rows,[`Business: ${state.business.name}`,`Branch: ${branch()?.name||'Main Branch'}`,`Period: ${today()} to ${today()}`,`Records: ${rows.length}`,...summary])}
function pdfDetailedSales(){const os=branchOrders(),rows=[];for(const o of os)for(const i of o.items||[])rows.push({order:o.id,date:o.date,time:o.time||'',customer:state.customers.find(c=>c.id===o.customerId)?.name||'Walk-in',item:i.name,qty:i.qty,amount:money(i.qty*i.price),pay:o.method});saveOpsReport('detailed-sales-report.pdf','DETAILED SALES REPORT',[{key:'order',label:'ORDER'},{key:'date',label:'DATE'},{key:'time',label:'TIME'},{key:'customer',label:'CUSTOMER'},{key:'item',label:'ITEM'},{key:'qty',label:'QTY'},{key:'amount',label:'AMOUNT'},{key:'pay',label:'PAYMODE'}],rows,[`Grand Total: ${money(os.reduce((a,o)=>a+o.total,0))}`])}
function pdfSalesByPaymode(){const groups={};for(const o of branchOrders())groups[o.method]=(groups[o.method]||0)+o.total;const rows=Object.entries(groups).map(([method,amount])=>({method,orders:branchOrders().filter(o=>o.method===method).length,amount:money(amount)}));saveOpsReport('sales-by-paymode.pdf','SALES REPORT BY PAYMODE',[{key:'method',label:'PAYMODE'},{key:'orders',label:'ORDERS'},{key:'amount',label:'AMOUNT'}],rows,[`Grand Total: ${money(rows.reduce((a,r)=>a+Number(String(r.amount).replace(/[^0-9.-]/g,''),0),0))}`])}
function pdfCreditCustomerStatement(){const rows=branchData(state.customers).filter(c=>(c.balance||0)>0).map(c=>({customer:c.name,phone:c.phone||'',limit:money(c.creditLimit||0),balance:money(c.balance||0),sales:money(state.creditSales.filter(x=>x.customerId===c.id&&x.branchId===state.currentBranchId).reduce((a,x)=>a+x.amount,0)),payments:money(state.creditRepayments.filter(x=>x.customerId===c.id&&x.branchId===state.currentBranchId).reduce((a,x)=>a+x.amount,0))}));saveOpsReport('credit-customer-statement.pdf','CREDIT CUSTOMER STATEMENT',[{key:'customer',label:'CUSTOMER'},{key:'phone',label:'PHONE'},{key:'limit',label:'LIMIT'},{key:'sales',label:'CREDIT SALES'},{key:'payments',label:'PAYMENTS'},{key:'balance',label:'BALANCE'}],rows)}
function pdfCreditCustomerPayments(){const rows=branchData(state.creditRepayments).map(r=>({date:r.date,customer:state.customers.find(c=>c.id===r.customerId)?.name||'',amount:money(r.amount),method:r.method,reference:r.reference||'—'}));saveOpsReport('credit-customer-payments.pdf','CREDIT CUSTOMER PAYMENTS REPORT',[{key:'date',label:'DATE'},{key:'customer',label:'CUSTOMER'},{key:'amount',label:'AMOUNT'},{key:'method',label:'METHOD'},{key:'reference',label:'REFERENCE'}],rows,[`Total: ${money(collectionTotal())}`])}
function pdfCapturedOrders(){const rows=branchOrders().map(o=>({order:o.id,date:o.date,customer:state.customers.find(c=>c.id===o.customerId)?.name||'Walk-in',status:o.paymentStatus||'paid',pay:o.method,total:money(o.total)}));saveOpsReport('captured-orders.pdf','CAPTURED ORDERS REPORT',[{key:'order',label:'ORDER'},{key:'date',label:'DATE'},{key:'customer',label:'CUSTOMER'},{key:'status',label:'STATUS'},{key:'pay',label:'PAYMODE'},{key:'total',label:'TOTAL'}],rows)}
function pdfOrdersSummary(){const groups={};for(const o of branchOrders()){const k=o.paymentStatus||o.method;groups[k]=(groups[k]||{orders:0,total:0});groups[k].orders++;groups[k].total+=o.total}const rows=Object.entries(groups).map(([status,v])=>({status,orders:v.orders,total:money(v.total)}));saveOpsReport('orders-summary.pdf','ORDERS SUMMARY REPORT',[{key:'status',label:'STATUS'},{key:'orders',label:'ORDERS'},{key:'total',label:'TOTAL'}],rows)}
function pdfSuppliersReport(){pdfSuppliers()}
function pdfSuppliersStatement(){const rows=branchData(state.suppliers).map(s=>({supplier:s.name,phone:s.phone||'',balance:money(s.balance||0),status:s.status||''}));saveOpsReport('suppliers-statement.pdf','SUPPLIERS STATEMENT REPORT',[{key:'supplier',label:'SUPPLIER'},{key:'phone',label:'PHONE'},{key:'balance',label:'BALANCE'},{key:'status',label:'STATUS'}],rows)}
function pdfSupplierStatement(){pdfSuppliersStatement()}
function pdfPriceList(){const rows=branchData(state.products).filter(p=>p.active).sort((a,b)=>a.category.localeCompare(b.category)||a.name.localeCompare(b.name)).map((p,i)=>({no:i+1,item:p.name,category:p.category,unit:p.unit,price:money(p.price)}));saveOpsReport('price-list.pdf','PRICE LIST REPORT',[{key:'no',label:'#'},{key:'item',label:'ITEM NAME'},{key:'category',label:'CATEGORY'},{key:'unit',label:'UNIT'},{key:'price',label:'SELLING PRICE'}],rows)}
function pdfStockBalance(){const rows=state.products.filter(p=>p.branchId===state.currentBranchId).map(p=>({item:p.name,category:p.category,stock:p.stock+' '+p.unit,cost:money(p.cost||0),value:money((p.cost||0)*p.stock)}));saveOpsReport('stock-balance.pdf','STOCK BALANCE REPORT',[{key:'item',label:'ITEM'},{key:'category',label:'CATEGORY'},{key:'stock',label:'BALANCE'},{key:'cost',label:'COST'},{key:'value',label:'STOCK VALUE'}],rows)}
function pdfStockBalanceByStore(){const rows=[];for(const b of state.branches){const ps=state.products.filter(p=>p.branchId===b.id);if(!ps.length)continue;rows.push({store:b.name,items:ps.length,units:ps.reduce((a,p)=>a+p.stock,0),value:money(ps.reduce((a,p)=>a+(p.cost||0)*p.stock,0))})}saveOpsReport('stock-balance-by-store.pdf','STOCK BALANCE BY STORE REPORT',[{key:'store',label:'STORE'},{key:'items',label:'ITEMS'},{key:'units',label:'UNITS'},{key:'value',label:'STOCK VALUE'}],rows)}
function pdfStockCard(){const moves=state.stockMovements||[];const rows=moves.filter(m=>m.branchId===state.currentBranchId).map(m=>({date:m.date,item:state.products.find(p=>p.id===m.productId)?.name||m.productId,type:m.type,qty:m.quantity,ref:m.reference||'—',user:m.user||''}));saveOpsReport('stock-card.pdf','STOCK CARD REPORT',[{key:'date',label:'DATE'},{key:'item',label:'ITEM'},{key:'type',label:'MOVEMENT'},{key:'qty',label:'QTY'},{key:'ref',label:'REFERENCE'},{key:'user',label:'USER'}],rows)}
function pdfStockReplenishment(){const rows=(state.stockMovements||[]).filter(m=>m.branchId===state.currentBranchId&&m.type==='replenishment').map(m=>({date:m.date,item:state.products.find(p=>p.id===m.productId)?.name||m.productId,qty:m.quantity,cost:money(m.unitCost||0),supplier:state.suppliers.find(s=>s.id===m.supplierId)?.name||'',ref:m.reference||'—'}));saveOpsReport('stock-replenishment.pdf','STOCK REPLENISHMENT REPORT',[{key:'date',label:'DATE'},{key:'item',label:'ITEM'},{key:'qty',label:'QTY'},{key:'cost',label:'UNIT COST'},{key:'supplier',label:'SUPPLIER'},{key:'ref',label:'REFERENCE'}],rows)}
function pdfRawMaterialRequisition(){const rows=(state.rawMaterialRequisitions||[]).filter(r=>r.branchId===state.currentBranchId).map(r=>({date:r.date,request:r.id,item:r.item||'',qty:r.quantity||0,department:r.department||'',status:r.status||'pending'}));saveOpsReport('raw-material-requisition.pdf','RAW MATERIAL REQUISATION REPORT',[{key:'date',label:'DATE'},{key:'request',label:'REQUEST'},{key:'item',label:'ITEM'},{key:'qty',label:'QTY'},{key:'department',label:'DEPARTMENT'},{key:'status',label:'STATUS'}],rows)}
function pdfSalesBySalesperson(){const g={};for(const o of branchOrders()){const k=o.cashier||'Unassigned';g[k]=(g[k]||{orders:0,total:0});g[k].orders++;g[k].total+=o.total}const rows=Object.entries(g).map(([salesperson,v])=>({salesperson,orders:v.orders,total:money(v.total)}));saveOpsReport('sales-by-salesperson.pdf','SALES REPORT BY SALESPERSON',[{key:'salesperson',label:'SALESPERSON'},{key:'orders',label:'ORDERS'},{key:'total',label:'SALES'}],rows)}
function pdfSalesByStores(){const b=branch(),os=branchOrders(),rows=[{store:b?.name||'Current Branch',orders:os.length,total:money(os.reduce((a,o)=>a+o.total,0))}];saveOpsReport('sales-by-stores.pdf','SALES REPORT BY STORES',[{key:'store',label:'STORE'},{key:'orders',label:'ORDERS'},{key:'total',label:'SALES'}],rows)}
function pdfCollectionByStore(){const b=branch(),ps=branchPayments().filter(p=>p.status==='paid'),rows=[{store:b?.name||'Current Branch',transactions:ps.length,total:money(ps.reduce((a,p)=>a+p.amount,0))}];saveOpsReport('collection-by-store.pdf','COLLECTION BY STORE REPORT',[{key:'store',label:'STORE'},{key:'transactions',label:'TRANSACTIONS'},{key:'total',label:'COLLECTION'}],rows)}
function pdfCollectionBySalesperson(){const g={};for(const p of state.payments.filter(p=>p.branchId===state.currentBranchId&&p.status==='paid')){const o=state.orders.find(x=>x.id===p.orderId);const k=o?.cashier||'Unassigned';g[k]=(g[k]||{transactions:0,total:0});g[k].transactions++;g[k].total+=p.amount}const rows=Object.entries(g).map(([salesperson,v])=>({salesperson,transactions:v.transactions,total:money(v.total)}));saveOpsReport('collection-by-salesperson.pdf','COLLECTION BY SALESPERSON REPORT',[{key:'salesperson',label:'SALESPERSON'},{key:'transactions',label:'TRANSACTIONS'},{key:'total',label:'COLLECTION'}],rows)}
function pdfStockProfitAnalysis(){const rows=productSales().map(x=>({item:x.name,qty:x.qty,sales:money(x.sales),cost:money(x.cost),profit:money(x.sales-x.cost)}));saveOpsReport('stock-profit-analysis.pdf','STOCK PROFIT ANALYSIS',[{key:'item',label:'ITEM'},{key:'qty',label:'SOLD QTY'},{key:'sales',label:'SALES'},{key:'cost',label:'COST'},{key:'profit',label:'EST. PROFIT'}],rows)}
function pdfStockSoldQuantityAnalysis(){const rows=productSales().sort((a,b)=>b.qty-a.qty).map(x=>({item:x.name,category:state.products.find(p=>p.id===x.id)?.category||'',qty:x.qty,amount:money(x.sales)}));saveOpsReport('stock-sold-quantity-analysis.pdf','STOCK SOLD QUANTITY ANALYSIS',[{key:'item',label:'ITEM'},{key:'category',label:'CATEGORY'},{key:'qty',label:'SOLD QTY'},{key:'amount',label:'SALES'}],rows)}
function verificationRows(){return (state.stockVerifications||[]).flatMap(v=>(v.items||[]).map(i=>({date:v.date||today(),item:i.name||i.item||'',system:i.systemQty??i.system??0,physical:i.physicalQty??i.physical??0,variance:(i.physicalQty??i.physical??0)-(i.systemQty??i.system??0),verifiedBy:v.verifiedBy||v.user||''})))}
function pdfStockVerificationLost(){const rows=verificationRows().filter(r=>r.variance<0).map(r=>({...r,variance:r.variance}));saveOpsReport('stock-verification-lost.pdf','STOCK VERIFICATION LOST ITEMS REPORT',[{key:'date',label:'DATE'},{key:'item',label:'ITEM'},{key:'system',label:'SYSTEM'},{key:'physical',label:'PHYSICAL'},{key:'variance',label:'LOST'},{key:'verifiedBy',label:'VERIFIED BY'}],rows)}
function pdfStockVerificationExcess(){const rows=verificationRows().filter(r=>r.variance>0);saveOpsReport('stock-verification-excess.pdf','STOCK VERIFICATION EXCESS ITEMS REPORT',[{key:'date',label:'DATE'},{key:'item',label:'ITEM'},{key:'system',label:'SYSTEM'},{key:'physical',label:'PHYSICAL'},{key:'variance',label:'EXCESS'},{key:'verifiedBy',label:'VERIFIED BY'}],rows)}
function pdfSupplierCreditPayments(){const rows=(state.supplierPayments||[]).filter(p=>p.branchId===state.currentBranchId).map(p=>({date:p.date, supplier:state.suppliers.find(s=>s.id===p.supplierId)?.name||'', amount:money(p.amount), method:p.method||'', reference:p.reference||''}));saveOpsReport('supplier-credit-payments.pdf','SUPPLIER CREDIT PAYMENTS REPORT',[{key:'date',label:'DATE'},{key:'supplier',label:'SUPPLIER'},{key:'amount',label:'AMOUNT'},{key:'method',label:'METHOD'},{key:'reference',label:'REFERENCE'}],rows)}
function pdfCreditCustomerSalesPayments(){const rows=[];for(const c of state.customers){const sales=state.creditSales.filter(r=>r.customerId===c.id&&r.branchId===state.currentBranchId).reduce((a,r)=>a+r.amount,0),payments=state.creditRepayments.filter(r=>r.customerId===c.id&&r.branchId===state.currentBranchId).reduce((a,r)=>a+r.amount,0);if(sales||payments)rows.push({customer:c.name,sales:money(sales),payments:money(payments),balance:money(c.balance||0)})}saveOpsReport('credit-customer-sales-payments.pdf','CREDIT CUSTOMER SALES & PAYMENTS REPORT',[{key:'customer',label:'CUSTOMER'},{key:'sales',label:'CREDIT SALES'},{key:'payments',label:'PAYMENTS'},{key:'balance',label:'BALANCE'}],rows)}
function pdfCreditNoteItems(){const rows=(state.creditNotes||[]).flatMap(n=>(n.items||[]).map(i=>({note:n.id,order:n.orderId||'',date:n.date||'',item:i.name||'',qty:i.qty||0,amount:money(i.amount||((i.qty||0)*(i.price||0)))})));saveOpsReport('credit-note-items.pdf','CREDIT NOTE ITEMS REPORT',[{key:'note',label:'CREDIT NOTE'},{key:'order',label:'ORDER'},{key:'date',label:'DATE'},{key:'item',label:'ITEM'},{key:'qty',label:'QTY'},{key:'amount',label:'AMOUNT'}],rows)}
function pdfCreditNoteByOrder(){const rows=(state.creditNotes||[]).map(n=>({note:n.id,order:n.orderId||'',date:n.date||'',customer:state.customers.find(c=>c.id===n.customerId)?.name||'',amount:money(n.amount||0),reason:n.reason||''}));saveOpsReport('credit-note-by-order.pdf','CREDIT NOTE BY ORDER NO REPORT',[{key:'note',label:'CREDIT NOTE'},{key:'order',label:'ORDER NO'},{key:'date',label:'DATE'},{key:'customer',label:'CUSTOMER'},{key:'amount',label:'AMOUNT'},{key:'reason',label:'REASON'}],rows)}
function pdfDetailedSalesByCustomer(){const rows=[];for(const o of branchOrders())for(const i of o.items||[])rows.push({customer:state.customers.find(c=>c.id===o.customerId)?.name||'Walk-in',order:o.id,date:o.date,item:i.name,qty:i.qty,amount:money(i.qty*i.price)});saveOpsReport('detailed-sales-by-customer.pdf','DETAILED SALES REPORT BY CUSTOMER',[{key:'customer',label:'CUSTOMER'},{key:'order',label:'ORDER'},{key:'date',label:'DATE'},{key:'item',label:'ITEM'},{key:'qty',label:'QTY'},{key:'amount',label:'AMOUNT'}],rows)}
function pdfDetailedSalesByStore(){const rows=[];for(const o of branchOrders())for(const i of o.items||[]){const b=branch();rows.push({store:b?.name||'Unknown',order:o.id,date:o.date,customer:state.customers.find(c=>c.id===o.customerId)?.name||'Walk-in',item:i.name,qty:i.qty,amount:money(i.qty*i.price)})}saveOpsReport('detailed-sales-by-store.pdf','DETAILED SALES REPORT BY STORE',[{key:'store',label:'STORE'},{key:'order',label:'ORDER'},{key:'date',label:'DATE'},{key:'customer',label:'CUSTOMER'},{key:'item',label:'ITEM'},{key:'qty',label:'QTY'},{key:'amount',label:'AMOUNT'}],rows)}
function pdfDetailedSalesByItemStore(){const rows=[];for(const o of branchOrders())for(const i of o.items||[])rows.push({item:i.name,store:branch()?.name||'Current Branch',qty:i.qty,amount:money(i.qty*i.price),order:o.id,date:o.date});saveOpsReport('detailed-sales-by-item-store.pdf','DETAILED SALES REPORT BY ITEM & STORE',[{key:'item',label:'ITEM'},{key:'store',label:'STORE'},{key:'qty',label:'QTY'},{key:'amount',label:'AMOUNT'},{key:'order',label:'ORDER'},{key:'date',label:'DATE'}],rows)}
function pdfSalesByCategory(){const g={};for(const o of branchOrders())for(const i of o.items||[]){const p=state.products.find(x=>x.id===i.id),k=p?.category||'Uncategorised';g[k]=(g[k]||{qty:0,total:0});g[k].qty+=i.qty;g[k].total+=i.qty*i.price}const rows=Object.entries(g).map(([category,v])=>({category,qty:v.qty,total:money(v.total)}));saveOpsReport('sales-by-item-category.pdf','SALES REPORT BY ITEM CATEGORY',[{key:'category',label:'CATEGORY'},{key:'qty',label:'QTY SOLD'},{key:'total',label:'SALES'}],rows)}
function pdfEscape(s){return String(s??'').replace(/\\/g,'\\\\').replace(/[()]/g,m=>'\\'+m).replace(/[^\x20-\x7E]/g,'?')}
function buildPdf(title,columns,rows,summary=[]){const W=595,H=842,rowsPerPage=44,pages=[];for(let i=0;i<rows.length||i===0;i+=rowsPerPage)pages.push(rows.slice(i,i+rowsPerPage));const all=[];let next=5,pageRefs=[],fontReg,fontBold;for(const pg of pages){const pageId=next++,contentId=next++;pageRefs.push(pageId);const lines=['BT','/F2 16 Tf','34 800 Td',`(${pdfEscape(title)}) Tj`,'/F1 8 Tf','0 -18 Td',`(${pdfEscape(state.business.name)}) Tj`,'0 -13 Td',`(${pdfEscape(state.business.address||state.business.location||'')}) Tj`,'0 -13 Td',`(${pdfEscape('Branch: '+(branch()?.name||'Main Branch')+'    Generated: '+new Date().toLocaleString('en-GB'))}) Tj`,'/F2 8 Tf','0 -18 Td',`(${pdfEscape(columns.map(c=>c.label).join(' | '))}) Tj`,'/F1 8 Tf'];for(const r of pg){lines.push('0 -15 Td',`(${pdfEscape(columns.map(c=>String(r[c.key]??'')).join(' | '))}) Tj`)}if(pg===pages[pages.length-1]&&summary.length){lines.push('/F2 9 Tf','0 -18 Td');for(const x of summary){lines.push(`(${pdfEscape(x)}) Tj`,'0 -13 Td')}}lines.push('/F1 7 Tf','0 -18 Td',`(${pdfEscape('HarborPOS • Page '+pageRefs.length)}) Tj`,'ET');all.push({pageId,contentId,stream:lines.join('\n')})}
const catalog=1,pagesId=4;fontReg=next++;fontBold=next++;const objs=[{id:catalog,obj:`1 0 obj<< /Type /Catalog /Pages 4 0 R >>endobj`},{id:pagesId,obj:`4 0 obj<< /Type /Pages /Kids [${pageRefs.map(x=>x+' 0 R').join(' ')}] /Count ${pageRefs.length} >>endobj`}];for(const o of all){objs.push({id:o.pageId,obj:`${o.pageId} 0 obj<< /Type /Page /Parent 4 0 R /MediaBox [0 0 ${W} ${H}] /Resources<< /Font<< /F1 ${fontReg} 0 R /F2 ${fontBold} 0 R >> >> /Contents ${o.contentId} 0 R >>endobj`},{id:o.contentId,obj:`${o.contentId} 0 obj<< /Length ${o.stream.length} >>stream\n${o.stream}\nendstream endobj`})}objs.push({id:fontReg,obj:`${fontReg} 0 obj<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>endobj`},{id:fontBold,obj:`${fontBold} 0 obj<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>endobj`});let pdf='%PDF-1.4\n',off={};for(const o of objs){off[o.id]=pdf.length;pdf+=o.obj+'\n'}const x=pdf.length,size=Math.max(...objs.map(o=>o.id))+1;pdf+='xref\n0 '+size+'\n0000000000 65535 f \n';for(let i=1;i<size;i++)pdf+=String(off[i]||0).padStart(10,'0')+' 00000 n \n';pdf+=`trailer<< /Size ${size} /Root ${catalog} 0 R >>\nstartxref\n${x}\n%%EOF`;return new Blob([pdf],{type:'application/pdf'})}
function savePdf(name,title,columns,rows,summary=[]){const a=document.createElement('a'),url=URL.createObjectURL(buildPdf(title,columns,rows,summary));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),800);toast(name+' downloaded')}
