function deleteEntity(type,id){
  const labels={order:'sale/order',customer:'customer',supplier:'supplier',product:'product',conversion:'stock conversion',credit:'credit sale',repayment:'repayment',room:'room',reservation:'reservation',stay:'guest stay',payment:'payment',branch:'branch',user:'staff account'};
  const label=labels[type]||'record';
  if(!confirm(`Delete this ${label}? This action cannot be undone.`))return;
  let note='';
  if(type==='order'){
    const o=state.orders.find(x=>x.id===id); if(!o){toast('Record not found');return;}
    state.orders=state.orders.filter(x=>x.id!==id);
    state.payments=(state.payments||[]).filter(x=>x.orderId!==id);
    state.creditSales=(state.creditSales||[]).filter(x=>x.orderId!==id);
    if(o.customerId){const c=state.customers.find(x=>x.id===o.customerId);const cr=(state.creditSales||[]).filter(x=>x.customerId===o.customerId).reduce((a,x)=>a+x.amount,0);const rp=(state.creditRepayments||[]).filter(x=>x.customerId===o.customerId).reduce((a,x)=>a+x.amount,0);if(c)c.balance=Math.max(0,cr-rp);}
    note=o.id;
  } else if(type==='customer'){
    const c=state.customers.find(x=>x.id===id); if(!c){toast('Record not found');return;}
    state.customers=state.customers.filter(x=>x.id!==id);
    state.creditRepayments=(state.creditRepayments||[]).filter(x=>x.customerId!==id);
    state.creditSales=(state.creditSales||[]).filter(x=>x.customerId!==id);
    note=c.name;
  } else if(type==='supplier'){
    const x=state.suppliers.find(v=>v.id===id); if(!x){toast('Record not found');return;}
    state.suppliers=state.suppliers.filter(v=>v.id!==id);
    state.supplierPayments=(state.supplierPayments||[]).filter(v=>v.supplierId!==id);
    (state.stockMovements||[]).forEach(v=>{if(v.supplierId===id)v.supplierId='';}); note=x.name;
  } else if(type==='product'){
    const x=state.products.find(v=>v.id===id); if(!x){toast('Record not found');return;}
    state.products=state.products.filter(v=>v.id!==id);
    state.stockMovements=(state.stockMovements||[]).filter(v=>v.productId!==id);
    state.stockVerifications=(state.stockVerifications||[]).map(v=>({...v,items:(v.items||[]).filter(i=>i.productId!==id)}));
    note=x.name;
  } else if(type==='conversion'){
    const x=state.stockConversions.find(v=>v.id===id); if(!x){toast('Record not found');return;}
    const from=state.products.find(v=>v.id===x.fromId),to=state.products.find(v=>v.id===x.toId); if(from)from.stock+=Number(x.inputQty)||0; if(to)to.stock=Math.max(0,to.stock-(Number(x.outputQty)||0));
    state.stockConversions=state.stockConversions.filter(v=>v.id!==id); note=x.id;
  } else if(type==='credit'){
    const x=state.creditSales.find(v=>v.id===id); if(!x){toast('Record not found');return;}
    state.creditSales=state.creditSales.filter(v=>v.id!==id); if(x.customerId){const c=state.customers.find(v=>v.id===x.customerId);if(c)c.balance=Math.max(0,(c.balance||0)-Number(x.amount||0));}
    state.payments=(state.payments||[]).filter(v=>v.orderId!==x.orderId); state.orders=(state.orders||[]).filter(v=>v.id!==x.orderId); note=x.id;
  } else if(type==='repayment'){
    const x=state.creditRepayments.find(v=>v.id===id); if(!x){toast('Record not found');return;}
    const c=state.customers.find(v=>v.id===x.customerId); if(c)c.balance=(c.balance||0)+Number(x.amount||0);
    state.creditRepayments=state.creditRepayments.filter(v=>v.id!==id); note=x.id;
  } else if(type==='room'){
    const x=state.rooms.find(v=>v.id===id); if(!x){toast('Record not found');return;}
    if(x.status==='occupied'){toast('Check out the guest before deleting this room');return;}
    state.rooms=state.rooms.filter(v=>v.id!==id); state.reservations=(state.reservations||[]).filter(v=>v.roomId!==id); note=x.no;
  } else if(type==='reservation'){
    const x=state.reservations.find(v=>v.id===id); if(!x){toast('Record not found');return;}
    state.reservations=state.reservations.filter(v=>v.id!==id); note=x.guest;
  } else if(type==='stay'){
    const x=state.stays.find(v=>v.id===id); if(!x){toast('Record not found');return;}
    state.stays=state.stays.filter(v=>v.id!==id); const room=state.rooms.find(v=>v.id===x.roomId); if(room)room.status='available'; note=x.guest;
  } else if(type==='payment'){
    const x=state.payments.find(v=>v.id===id); if(!x){toast('Record not found');return;}
    state.payments=state.payments.filter(v=>v.id!==id); note=x.id;
  } else if(type==='branch'){
    const x=state.branches.find(v=>v.id===id); if(!x){toast('Record not found');return;}
    if(state.branches.length<=1){toast('At least one branch must remain');return;}
    state.branches=state.branches.filter(v=>v.id!==id); state.users.forEach(u=>u.branchIds=(u.branchIds||[]).filter(b=>b!==id));
    if(state.currentBranchId===id)state.currentBranchId=state.branches[0].id; note=x.name;
  } else if(type==='user'){
    const x=state.users.find(v=>v.id===id); if(!x){toast('Record not found');return;}
    const me=currentUser(); if(me&&me.id===id){toast('You cannot delete the account currently signed in');return;}
    if(x.level===1&&state.users.filter(v=>v.level===1&&v.active!==false).length<=1){toast('Keep at least one active owner account');return;}
    state.users=state.users.filter(v=>v.id!==id); note=x.name;
  } else {toast('Unsupported delete action');return;}
  audit(`${label} deleted`,type,note); save(); closeModal(); toast(`${label.charAt(0).toUpperCase()+label.slice(1)} deleted`); render();
}
